import { Box, Button, Paper, Stack, Typography } from '@mui/material';
import { FitAddon } from '@xterm/addon-fit';
import { Terminal } from '@xterm/xterm';
import '@xterm/xterm/css/xterm.css';
import { useEffect, useRef, useState } from 'react';
import { monoFont } from '../../theme.js';

export default function TerminalPanel({ pod, tunnelLabel, visible }) {
  const hostRef = useRef(null);
  const terminalRef = useRef(null);
  const fitRef = useRef(null);
  const socketRef = useRef(null);
  const [socketGeneration, setSocketGeneration] = useState(0);
  const [connected, setConnected] = useState(false);
  const [socketError, setSocketError] = useState('');

  useEffect(() => {
    const terminal = new Terminal({
      cursorBlink: true,
      convertEol: true,
      fontFamily: monoFont,
      fontSize: 13,
      theme: { background: '#0e1714', foreground: '#dce8dc' },
    });
    const fit = new FitAddon();
    terminal.loadAddon(fit);
    terminal.open(hostRef.current);
    terminalRef.current = terminal;
    fitRef.current = fit;
    const input = terminal.onData((data) => {
      if (socketRef.current?.readyState === WebSocket.OPEN) socketRef.current.send(data);
    });
    const resizeObserver = new ResizeObserver(() => {
      if (hostRef.current?.offsetParent) {
        try { fit.fit(); } catch (_) { /* Hidden containers cannot be measured. */ }
      }
    });
    resizeObserver.observe(hostRef.current);
    requestAnimationFrame(() => {
      try { fit.fit(); } catch (_) { /* Initial layout may still be hidden. */ }
    });
    return () => {
      resizeObserver.disconnect();
      input.dispose();
      terminal.dispose();
      terminalRef.current = null;
      fitRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!visible) return;
    requestAnimationFrame(() => {
      try { fitRef.current?.fit(); } catch (_) { /* Ignore transient layout changes. */ }
    });
  }, [visible]);

  useEffect(() => {
    if (!pod) return undefined;
    const previous = socketRef.current;
    if (previous) {
      previous.onmessage = null;
      previous.onopen = null;
      previous.onclose = null;
      previous.onerror = null;
      previous.close();
    }
    setConnected(false);
    setSocketError('');
    const protocol = window.location.protocol === 'https:' ? 'wss://' : 'ws://';
    const socket = new WebSocket(`${protocol}${window.location.host}/ws/pods/${encodeURIComponent(pod)}/terminal`);
    socketRef.current = socket;
    socket.onmessage = (event) => terminalRef.current?.write(event.data);
    socket.onopen = () => {
      if (socketRef.current !== socket) return;
      setConnected(true);
      setSocketError('');
      requestAnimationFrame(() => {
        try { fitRef.current?.fit(); } catch (_) { /* Ignore transient layout changes. */ }
      });
    };
    socket.onerror = () => {
      if (socketRef.current === socket) setSocketError('终端连接错误');
    };
    socket.onclose = () => {
      if (socketRef.current !== socket) return;
      setConnected(false);
      setSocketError((current) => current || '终端连接已关闭');
    };
    return () => {
      socket.onmessage = null;
      socket.onopen = null;
      socket.onclose = null;
      socket.onerror = null;
      socket.close();
      if (socketRef.current === socket) socketRef.current = null;
    };
  }, [pod, socketGeneration]);

  return (
    <Paper variant="outlined" sx={{ overflow: 'hidden' }}>
      <Stack direction="row" sx={{ minHeight: 44, px: 2, borderBottom: 1, borderColor: 'divider', alignItems: 'center', justifyContent: 'space-between' }}>
        <Typography variant="h6">终端</Typography>
        <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
          <Typography variant="body2" color={socketError ? 'error' : 'text.secondary'}>
            {tunnelLabel}{connected ? '' : '（已断开）'}{socketError ? ` · ${socketError}` : ''}
          </Typography>
          {!connected ? <Button size="small" variant="outlined" onClick={() => setSocketGeneration((value) => value + 1)}>重连</Button> : null}
        </Stack>
      </Stack>
      <Box ref={hostRef} sx={{ height: { xs: 280, md: 320, lg: 360 }, p: 1, bgcolor: '#0e1714', '& .xterm': { height: '100%' } }} />
    </Paper>
  );
}
