import {
  Alert, Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, List, ListItemButton,
  ListItemText, Radio, Stack, Typography,
} from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import { api, jsonOptions, podUrl } from '../../api.js';
import { TextInputDialog } from '../../components/Dialogs.jsx';
import { monoFont } from '../../theme.js';
import { joinRemotePath, parentPath } from '../../utils.js';

export default function FilesystemPickerDialog({ open, side, mode, pod, initialPath, remoteRoot, onClose, onSelect }) {
  const [path, setPath] = useState('');
  const [entries, setEntries] = useState([]);
  const [selection, setSelection] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [creating, setCreating] = useState(false);
  const loadToken = useRef(0);
  const sourceMode = mode === 'source';

  const load = useCallback(async (requestedPath) => {
    const token = ++loadToken.current;
    setEntries([]);
    setSelection(null);
    setError('');
    if (side === 'remote' && !pod) {
      setLoading(false);
      setError('请先连接 Pod');
      return;
    }
    setLoading(true);
    try {
      let data;
      if (side === 'local') {
        data = await api(`/api/oss/local-directories?path=${encodeURIComponent(requestedPath || '')}${sourceMode ? '&files=true' : ''}`);
      } else {
        const response = await api(`${podUrl(pod, '/files')}?path=${encodeURIComponent(requestedPath)}`);
        data = { path: response.path, entries: sourceMode ? response.entries : (response.entries || []).filter((entry) => entry.kind === 'd') };
      }
      if (token !== loadToken.current) return;
      setPath(data.path);
      setEntries(Array.isArray(data.entries) ? data.entries : []);
      setSelection(null);
    } catch (requestError) {
      if (token === loadToken.current) setError(`读取目录失败：${requestError.message}`);
    } finally {
      if (token === loadToken.current) setLoading(false);
    }
  }, [pod, side, sourceMode]);

  useEffect(() => {
    if (!open) { loadToken.current += 1; return; }
    load(initialPath || (side === 'local' ? '' : (remoteRoot || '/root')));
    return () => { loadToken.current += 1; };
  }, [open, side, initialPath, remoteRoot, load]);

  const createDirectory = async (name) => {
    setCreating(false);
    try {
      const endpoint = side === 'local' ? '/api/oss/local-directories' : podUrl(pod, '/directories');
      const data = await api(endpoint, jsonOptions('POST', { path, name }));
      onSelect({ path: data.path, kind: 'directory' });
    } catch (requestError) {
      setError(`创建目录失败：${requestError.message}`);
    }
  };

  const directories = entries.filter((entry) => entry.kind === 'd');
  const files = sourceMode ? entries.filter((entry) => entry.kind === 'f') : [];
  const title = side === 'local'
    ? (sourceMode ? '选择本机文件或目录' : '选择本机目录')
    : (sourceMode ? '选择 Pod 文件或目录' : '选择 Pod 目录');

  return (
    <>
      <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
        <DialogTitle>{title}</DialogTitle>
        <DialogContent dividers>
          <Typography variant="body2" color="text.secondary" sx={{ fontFamily: monoFont, overflowWrap: 'anywhere', mb: 1 }}>{path}</Typography>
          {error ? <Alert severity="error" sx={{ mb: 1 }}>{error}</Alert> : null}
          <Box sx={{ minHeight: 240, maxHeight: 420, overflow: 'auto', border: 1, borderColor: 'divider', borderRadius: 1 }}>
            <List dense disablePadding>
              {directories.map((entry) => (
                <ListItemButton key={`d:${entry.name}`} onClick={() => load(joinRemotePath(path, entry.name))}>
                  <ListItemText primary={`📁 ${entry.name}/`} primaryTypographyProps={{ fontFamily: monoFont }} />
                </ListItemButton>
              ))}
              {files.map((entry) => {
                const fullPath = joinRemotePath(path, entry.name);
                return (
                  <ListItemButton key={`f:${entry.name}`} selected={selection?.path === fullPath} onClick={() => setSelection({ path: fullPath, kind: 'file' })}>
                    <Radio size="small" checked={selection?.path === fullPath} tabIndex={-1} />
                    <ListItemText primary={entry.name} primaryTypographyProps={{ fontFamily: monoFont }} />
                  </ListItemButton>
                );
              })}
            </List>
            {!loading && !entries.length && !error ? <Typography color="text.secondary" align="center" sx={{ py: 6 }}>没有内容</Typography> : null}
          </Box>
        </DialogContent>
        <DialogActions sx={{ justifyContent: 'space-between', flexWrap: 'wrap' }}>
          <Stack direction="row" spacing={1}>
            <Button variant="outlined" disabled={loading || path === '/'} onClick={() => load(parentPath(path))}>上级</Button>
            {!sourceMode ? <Button variant="outlined" disabled={loading} onClick={() => setCreating(true)}>新建文件夹</Button> : null}
          </Stack>
          <Stack direction="row" spacing={1}>
            <Button onClick={onClose}>关闭</Button>
            <Button variant="contained" disabled={loading || !!error} onClick={() => onSelect(selection || { path, kind: 'directory' })}>{selection ? '确认选择文件' : '选择当前目录'}</Button>
          </Stack>
        </DialogActions>
      </Dialog>
      <TextInputDialog open={creating} title="新建文件夹" label="文件夹名称" onClose={() => setCreating(false)} onConfirm={createDirectory} />
    </>
  );
}
