import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  TextField,
} from '@mui/material';
import { useEffect, useState } from 'react';

export function ConfirmDialog({ open, title = '请确认', message, confirmText = '确认', danger = false, busy = false, onConfirm, onClose }) {
  return (
    <Dialog open={open} onClose={busy ? undefined : onClose} maxWidth="xs" fullWidth>
      <DialogTitle>{title}</DialogTitle>
      <DialogContent><DialogContentText sx={{ whiteSpace: 'pre-line' }}>{message}</DialogContentText></DialogContent>
      <DialogActions>
        <Button type="button" onClick={onClose} disabled={busy}>取消</Button>
        <Button type="button" color={danger ? 'error' : 'primary'} variant="contained" onClick={onConfirm} disabled={busy}>{confirmText}</Button>
      </DialogActions>
    </Dialog>
  );
}

export function TextInputDialog({ open, title, label, initialValue = '', confirmText = '确认', onConfirm, onClose }) {
  const [value, setValue] = useState(initialValue);
  useEffect(() => {
    if (open) setValue(initialValue);
  }, [open, initialValue]);

  const submit = (event) => {
    event.preventDefault();
    const trimmed = value.trim();
    if (trimmed) onConfirm(trimmed);
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="xs"
      fullWidth
      slotProps={{ paper: { component: 'form', onSubmit: submit, noValidate: true } }}
    >
      <DialogTitle>{title}</DialogTitle>
      <DialogContent>
        <TextField autoFocus fullWidth label={label} value={value} onChange={(event) => setValue(event.target.value)} sx={{ mt: 1 }} required />
      </DialogContent>
      <DialogActions>
        <Button type="button" onClick={onClose}>取消</Button>
        <Button type="submit" variant="contained">{confirmText}</Button>
      </DialogActions>
    </Dialog>
  );
}
