import {
  Alert, Autocomplete, Box, Button, Paper, Stack, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, TextField, Typography,
} from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import { monoFont } from '../../theme.js';
import { formatBytes } from '../../utils.js';
import OssBreadcrumbs from './OssBreadcrumbs.jsx';

export default function OssObjectBrowser({ active, user, users, ready, busy, objectStore, refreshNonce, onUserChange, onDownload }) {
  const [prefix, setPrefix] = useState('');
  const [entries, setEntries] = useState(null);
  const [status, setStatus] = useState({ text: '点击刷新查看对象', severity: 'info' });
  const requestToken = useRef(0);
  const currentContext = useRef('');
  const previousUser = useRef(user);
  const previousActive = useRef(active);
  const pendingRootRefresh = useRef(false);
  const previousNonce = useRef(-1);
  currentContext.current = `${user.trim()}\u0000${prefix}`;

  const refresh = useCallback(async (force = false, requestedPrefix = prefix) => {
    const snapshotUser = user.trim();
    const snapshotContext = `${snapshotUser}\u0000${requestedPrefix}`;
    const token = ++requestToken.current;
    if (!snapshotUser) {
      setStatus({ text: '请填写 OSS 用户', severity: 'error' });
      return;
    }
    if (!ready) {
      setStatus({ text: '本机 OSS 工具或配置尚未就绪', severity: 'warning' });
      return;
    }
    setStatus({ text: '正在加载当前目录…', severity: 'info' });
    try {
      const objects = await objectStore.load('local', snapshotUser, requestedPrefix, force, null);
      if (token !== requestToken.current || objects === null || currentContext.current !== snapshotContext) return;
      setEntries(objects);
      const directories = objects.filter((entry) => entry.kind === 'directory').length;
      setStatus({ text: `${directories} 个目录，${objects.length - directories} 个文件`, severity: 'info' });
    } catch (error) {
      if (token !== requestToken.current) return;
      setEntries([]);
      setStatus({ text: `加载失败：${error.message}`, severity: 'error' });
    }
  }, [objectStore, prefix, ready, user]);

  useEffect(() => {
    if (previousUser.current === user) return;
    previousUser.current = user;
    requestToken.current += 1;
    objectStore.invalidate();
    setPrefix('');
    setEntries(null);
    setStatus({ text: '点击刷新查看当前目录', severity: 'info' });
    if (active && user.trim() && ready) {
      pendingRootRefresh.current = false;
      refresh(false, '');
    } else {
      pendingRootRefresh.current = true;
    }
  }, [active, objectStore, ready, refresh, user]);

  useEffect(() => {
    const becameActive = active && !previousActive.current;
    previousActive.current = active;
    if (!becameActive || !user.trim() || !ready) return;
    const requestedPrefix = pendingRootRefresh.current ? '' : prefix;
    pendingRootRefresh.current = false;
    refresh(false, requestedPrefix);
  }, [active, prefix, ready, refresh, user]);

  useEffect(() => {
    if (!active || previousNonce.current === refreshNonce) return;
    previousNonce.current = refreshNonce;
    refresh(true);
  }, [active, refresh, refreshNonce]);

  useEffect(() => () => { requestToken.current += 1; }, []);

  const openPrefix = (nextPrefix) => {
    requestToken.current += 1;
    objectStore.invalidate();
    setPrefix(nextPrefix);
    setEntries(null);
    refresh(false, nextPrefix);
  };

  return (
    <Paper variant="outlined" sx={{ p: 2 }} aria-labelledby="oss-object-manager-title">
      <Stack spacing={1.25}>
        <Stack direction={{ xs: 'column', md: 'row' }} sx={{ alignItems: { md: 'center' }, justifyContent: 'space-between', gap: 1.5 }}>
          <Typography id="oss-object-manager-title" variant="h6">OSS 对象</Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ alignItems: { sm: 'center' } }}>
            <Autocomplete freeSolo options={users || []} inputValue={user} onInputChange={(_, value) => onUserChange(value)} sx={{ minWidth: { sm: 240 } }} renderInput={(params) => <TextField {...params} label="OSS 用户" autoComplete="off" />} />
            <Button variant="outlined" disabled={busy || !user.trim() || !ready} onClick={() => refresh(true)}>刷新</Button>
          </Stack>
        </Stack>
        <Alert severity={status.severity}>{status.text}</Alert>
        <OssBreadcrumbs prefix={prefix} onOpen={openPrefix} />
        <TableContainer sx={{ maxHeight: 480, border: 1, borderColor: 'divider', borderRadius: 1 }}>
          <Table stickyHeader size="small">
            <TableHead><TableRow><TableCell>名称</TableCell><TableCell width={110}>大小</TableCell><TableCell width={190}>修改时间</TableCell><TableCell align="right" width={170}>操作</TableCell></TableRow></TableHead>
            <TableBody>
              {(entries || []).map((entry) => entry.kind === 'directory' ? (
                <TableRow key={entry.key} sx={{ bgcolor: 'background.default' }}>
                  <TableCell><Button size="small" variant="text" onClick={() => openPrefix(entry.key)} sx={{ p: 0, minHeight: 30, fontFamily: monoFont }}>📁 {entry.name}/</Button></TableCell>
                  <TableCell>目录</TableCell><TableCell>—</TableCell>
                  <TableCell align="right"><Stack direction="row" spacing={0.5} sx={{ justifyContent: 'flex-end' }}><Button size="small" variant="outlined" onClick={() => openPrefix(entry.key)}>打开</Button><Button size="small" variant="outlined" onClick={() => onDownload('prefix', entry.key)}>下载</Button></Stack></TableCell>
                </TableRow>
              ) : (
                <TableRow key={entry.key}>
                  <TableCell sx={{ fontFamily: monoFont, maxWidth: 440, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={entry.key}>{entry.name}</TableCell>
                  <TableCell>{formatBytes(entry.size)}</TableCell><TableCell title={entry.modified || ''}>{entry.modified || '—'}</TableCell>
                  <TableCell align="right"><Button size="small" variant="outlined" onClick={() => onDownload('object', entry.key)}>下载</Button></TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {entries === null ? <Typography color="text.secondary" align="center" sx={{ py: 5 }}>点击刷新查看当前目录</Typography> : null}
          {entries !== null && !entries.length && status.severity !== 'error' ? <Typography color="text.secondary" align="center" sx={{ py: 5 }}>当前目录为空</Typography> : null}
          {entries !== null && !entries.length && status.severity === 'error' ? <Typography color="error" align="center" sx={{ py: 5 }}>无法读取当前目录</Typography> : null}
        </TableContainer>
      </Stack>
    </Paper>
  );
}
