import {
  Alert,
  Box,
  Breadcrumbs,
  Button,
  Checkbox,
  FormControlLabel,
  LinearProgress,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import { api, jsonOptions, normalizeDetail, podUrl } from '../../api.js';
import { monoFont } from '../../theme.js';
import { formatBytes, joinRemotePath, MAX_UPLOAD_BYTES, parentPath } from '../../utils.js';
import { ConfirmDialog, TextInputDialog } from '../../components/Dialogs.jsx';

const emptyStatus = { message: '', severity: 'info' };

export default function FileBrowser({ pod, remoteRoot }) {
  const [path, setPath] = useState(remoteRoot);
  const pathRef = useRef(remoteRoot);
  const [pathInput, setPathInput] = useState(remoteRoot);
  const [entries, setEntries] = useState([]);
  const [showHidden, setShowHidden] = useState(false);
  const [status, setStatus] = useState(emptyStatus);
  const [loading, setLoading] = useState(false);
  const [dialog, setDialog] = useState(null);
  const [downloadBusy, setDownloadBusy] = useState(new Set());
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [uploadBusy, setUploadBusy] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(null);
  const [uploadStatus, setUploadStatus] = useState('');
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef(null);
  const fileLoadToken = useRef(0);
  const podRef = useRef(pod);
  const podGeneration = useRef(0);
  const uploadRequestsRef = useRef(new Set());
  const framesRef = useRef(new Set());

  const setCurrentPath = (value) => {
    pathRef.current = value;
    setPath(value);
    setPathInput(value);
  };

  const isCurrentPod = (targetPod, generation) => podRef.current === targetPod && podGeneration.current === generation;

  const loadFiles = useCallback(async (
    requestedPath = pathRef.current,
    hidden = showHidden,
    targetPod = podRef.current,
    generation = podGeneration.current,
  ) => {
    if (!targetPod || podRef.current !== targetPod || podGeneration.current !== generation) return false;
    const token = ++fileLoadToken.current;
    setLoading(true);
    setStatus({ message: '正在读取远程目录…', severity: 'info' });
    try {
      const data = await api(`${podUrl(targetPod, '/files')}?path=${encodeURIComponent(requestedPath)}&show_hidden=${hidden}`);
      if (token !== fileLoadToken.current || podRef.current !== targetPod || podGeneration.current !== generation) return false;
      setCurrentPath(data.path);
      setEntries([...(data.entries || [])].sort((a, b) => (b.kind === 'd') - (a.kind === 'd') || String(a.name).localeCompare(String(b.name))));
      setStatus(emptyStatus);
      return true;
    } catch (error) {
      if (token !== fileLoadToken.current || podRef.current !== targetPod || podGeneration.current !== generation) return false;
      setPathInput(pathRef.current);
      setEntries([]);
      setStatus({ message: `读取目录失败：${error.message}`, severity: 'error' });
      return false;
    } finally {
      if (token === fileLoadToken.current && podRef.current === targetPod && podGeneration.current === generation) setLoading(false);
    }
  }, [showHidden]);

  useEffect(() => {
    fileLoadToken.current += 1;
    podGeneration.current += 1;
    podRef.current = pod;
    for (const request of uploadRequestsRef.current) request.abort();
    uploadRequestsRef.current.clear();
    setUploadBusy(false);
    setUploadProgress(null);
    setUploadStatus('');
    setSelectedFiles([]);
    setDownloadBusy(new Set());
    if (fileInputRef.current) fileInputRef.current.value = '';
    setCurrentPath(remoteRoot);
    setEntries([]);
    loadFiles(remoteRoot, showHidden, pod, podGeneration.current);
    return () => {
      fileLoadToken.current += 1;
      podGeneration.current += 1;
      if (podRef.current === pod) podRef.current = null;
      for (const request of uploadRequestsRef.current) request.abort();
      uploadRequestsRef.current.clear();
    };
  }, [pod, remoteRoot]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => () => {
    for (const frame of framesRef.current) frame.remove();
    framesRef.current.clear();
  }, []);

  const showTemporaryStatus = (
    message,
    severity = 'success',
    delay = 4000,
    targetPod = podRef.current,
    generation = podGeneration.current,
  ) => {
    if (!isCurrentPod(targetPod, generation)) return;
    setStatus({ message, severity });
    window.setTimeout(() => {
      if (isCurrentPod(targetPod, generation)) {
        setStatus((current) => current.message === message ? emptyStatus : current);
      }
    }, delay);
  };

  const createDirectory = async (name) => {
    setDialog(null);
    const targetPod = podRef.current;
    const generation = podGeneration.current;
    try {
      await api(podUrl(targetPod, '/directories'), jsonOptions('POST', { path: pathRef.current, name }));
      if (!isCurrentPod(targetPod, generation)) return;
      if (await loadFiles(pathRef.current, showHidden, targetPod, generation)) showTemporaryStatus(`已创建目录：${name}`);
    } catch (error) {
      if (isCurrentPod(targetPod, generation)) setStatus({ message: `创建目录失败：${error.message}`, severity: 'error' });
    }
  };

  const renameEntry = async (newName) => {
    const target = dialog;
    const targetPod = podRef.current;
    const generation = podGeneration.current;
    setDialog(null);
    if (!target || newName === target.name) return;
    try {
      await api(podUrl(targetPod, '/files/rename'), jsonOptions('POST', { path: target.path, name: newName }));
      if (!isCurrentPod(targetPod, generation)) return;
      if (await loadFiles(pathRef.current, showHidden, targetPod, generation)) showTemporaryStatus(`已重命名：${target.name} → ${newName}`);
    } catch (error) {
      if (isCurrentPod(targetPod, generation)) setStatus({ message: `重命名失败：${error.message}`, severity: 'error' });
    }
  };

  const deleteEntry = async () => {
    const target = dialog;
    const targetPod = podRef.current;
    const generation = podGeneration.current;
    setDialog(null);
    if (!target) return;
    try {
      await api(`${podUrl(targetPod, '/files')}?path=${encodeURIComponent(target.path)}`, { method: 'DELETE' });
      if (!isCurrentPod(targetPod, generation)) return;
      if (await loadFiles(pathRef.current, showHidden, targetPod, generation)) showTemporaryStatus(`已删除：${target.name}`);
    } catch (error) {
      if (isCurrentPod(targetPod, generation)) setStatus({ message: `删除失败：${error.message}`, severity: 'error' });
    }
  };

  const downloadEntry = async (entryPath, kind) => {
    const targetPod = podRef.current;
    const generation = podGeneration.current;
    const key = `${kind}:${entryPath}`;
    setDownloadBusy((current) => new Set(current).add(key));
    setStatus({ message: kind === 'directory' ? '正在检查目录并准备压缩下载…' : '正在准备文件下载…', severity: 'info' });
    try {
      const info = await api(`${podUrl(targetPod, '/files/download-info')}?path=${encodeURIComponent(entryPath)}&kind=${encodeURIComponent(kind)}`);
      if (!isCurrentPod(targetPod, generation)) return;
      const endpoint = kind === 'directory' ? 'directories/download' : 'files/download';
      const frame = document.createElement('iframe');
      frame.hidden = true;
      framesRef.current.add(frame);
      frame.onload = () => {
        if (!isCurrentPod(targetPod, generation)) {
          framesRef.current.delete(frame);
          frame.remove();
          return;
        }
        try {
          const text = frame.contentDocument?.body?.textContent?.trim();
          if (text) {
            const data = JSON.parse(text);
            if (data.detail) setStatus({ message: `下载失败：${normalizeDetail(data.detail)}`, severity: 'error' });
          }
        } catch (_) { /* A successful binary response is not readable as JSON. */ }
        framesRef.current.delete(frame);
        frame.remove();
      };
      frame.src = `${podUrl(targetPod, `/${endpoint}`)}?path=${encodeURIComponent(entryPath)}`;
      document.body.appendChild(frame);
      window.setTimeout(() => {
        framesRef.current.delete(frame);
        frame.remove();
      }, 60000);
      const message = kind === 'directory' ? `已开始打包并下载：${info.filename}` : `已开始下载：${info.filename}`;
      showTemporaryStatus(message, 'success', 5000);
    } catch (error) {
      if (isCurrentPod(targetPod, generation)) setStatus({ message: `下载失败：${error.message}`, severity: 'error' });
    } finally {
      if (isCurrentPod(targetPod, generation)) {
        setDownloadBusy((current) => {
          const next = new Set(current);
          next.delete(key);
          return next;
        });
      }
    }
  };

  const uploadOne = (file, uploadPod, uploadDirectory, generation) => new Promise((resolve) => {
    if (!isCurrentPod(uploadPod, generation)) {
      resolve();
      return;
    }
    const targetPath = joinRemotePath(uploadDirectory, file.name);
    const request = new XMLHttpRequest();
    uploadRequestsRef.current.add(request);
    const form = new FormData();
    form.append('path', targetPath);
    form.append('file', file);
    setUploadProgress(0);
    request.open('POST', `${podUrl(uploadPod, '/files/upload')}?path=${encodeURIComponent(targetPath)}`);
    request.upload.onprogress = (event) => {
      if (event.lengthComputable && isCurrentPod(uploadPod, generation)) setUploadProgress((event.loaded / event.total) * 100);
    };
    request.onload = async () => {
      uploadRequestsRef.current.delete(request);
      if (!isCurrentPod(uploadPod, generation)) {
        resolve();
        return;
      }
      let message = `上传成功：${file.name}`;
      if (request.status >= 300) {
        try {
          const payload = JSON.parse(request.responseText);
          message = `上传失败：${normalizeDetail(payload.detail) || request.status}`;
        } catch (_) {
          message = `上传失败：${request.status}`;
        }
      }
      setUploadStatus(message);
      if (request.status < 300) await loadFiles(pathRef.current, showHidden, uploadPod, generation);
      resolve();
    };
    request.onerror = () => {
      uploadRequestsRef.current.delete(request);
      if (isCurrentPod(uploadPod, generation)) setUploadStatus('上传失败：网络错误');
      resolve();
    };
    request.onabort = () => {
      uploadRequestsRef.current.delete(request);
      resolve();
    };
    request.send(form);
  });

  const uploadFiles = async (files) => {
    const queue = Array.from(files || []);
    if (!queue.length || uploadBusy) return;
    const uploadPod = podRef.current;
    const generation = podGeneration.current;
    setUploadBusy(true);
    for (const file of queue) {
      if (!isCurrentPod(uploadPod, generation)) break;
      if (file.size > MAX_UPLOAD_BYTES) {
        setUploadStatus(`文件过大：${file.name}（${formatBytes(file.size)}）`);
        continue;
      }
      await uploadOne(file, uploadPod, pathRef.current, generation);
    }
    if (!isCurrentPod(uploadPod, generation)) return;
    setUploadBusy(false);
    setSelectedFiles([]);
    if (fileInputRef.current) fileInputRef.current.value = '';
    window.setTimeout(() => {
      if (isCurrentPod(uploadPod, generation)) setUploadProgress(null);
    }, 1200);
  };

  const parts = path.split('/').filter(Boolean);
  const breadcrumbs = [{ label: '/', value: '/' }, ...parts.map((part, index) => ({
    label: part,
    value: `/${parts.slice(0, index + 1).join('/')}`,
  }))];

  return (
    <Paper
      variant="outlined"
      onDragOver={(event) => { event.preventDefault(); setDragOver(true); }}
      onDragLeave={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setDragOver(false); }}
      onDrop={(event) => { event.preventDefault(); setDragOver(false); uploadFiles(event.dataTransfer.files); }}
      sx={{ overflow: 'hidden', outline: dragOver ? '2px solid' : 'none', outlineColor: 'primary.main', outlineOffset: -2 }}
    >
      <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ p: 1.5, borderBottom: 1, borderColor: 'divider', alignItems: { md: 'center' }, justifyContent: 'space-between' }}>
        <Stack direction="row" spacing={1} sx={{ alignItems: 'baseline' }}>
          <Typography variant="h6">Pod 文件</Typography>
          <Typography variant="body2" color="text.secondary">{entries.length} 项</Typography>
        </Stack>
        <Stack direction="row" spacing={1} useFlexGap sx={{ alignItems: 'center', flexWrap: 'wrap' }}>
          <Button size="small" variant="outlined" onClick={() => setDialog({ type: 'create' })}>新建目录</Button>
          <Button size="small" variant="outlined" disabled={path === '/'} onClick={() => loadFiles(parentPath(path))}>上级</Button>
          <Button size="small" variant="outlined" disabled={loading} onClick={() => loadFiles()}>刷新</Button>
          <FormControlLabel
            sx={{ mr: 0 }}
            control={<Checkbox size="small" checked={showHidden} onChange={(event) => { setShowHidden(event.target.checked); loadFiles(pathRef.current, event.target.checked); }} />}
            label={<Typography variant="body2">显示隐藏</Typography>}
          />
        </Stack>
      </Stack>

      <Stack component="form" direction={{ xs: 'column', sm: 'row' }} spacing={1} onSubmit={(event) => { event.preventDefault(); if (pathInput.trim()) loadFiles(pathInput.trim()); }} sx={{ px: 1.5, pt: 1.5, alignItems: { sm: 'center' } }}>
        <Typography component="label" htmlFor="remote-path" variant="body2" sx={{ whiteSpace: 'nowrap' }}>远程路径</Typography>
        <TextField id="remote-path" fullWidth value={pathInput} onChange={(event) => setPathInput(event.target.value)} inputProps={{ spellCheck: false }} sx={{ '& input': { fontFamily: monoFont } }} required />
        <Button type="submit" variant="contained">打开</Button>
      </Stack>

      <Breadcrumbs aria-label="远程路径导航" sx={{ px: 1.5, py: 1, '& .MuiBreadcrumbs-separator': { mx: 0.25 } }}>
        {breadcrumbs.map((crumb) => <Button size="small" variant="text" key={crumb.value} disabled={crumb.value === path} onClick={() => loadFiles(crumb.value)} sx={{ minWidth: 28, px: 0.5, fontFamily: monoFont }}>{crumb.label}</Button>)}
      </Breadcrumbs>

      <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ px: 1.5, pb: 1.5, alignItems: { md: 'center' } }}>
        <Button size="small" variant="outlined" component="label" disabled={uploadBusy}>
          选择文件
          <input ref={fileInputRef} hidden type="file" multiple onChange={(event) => setSelectedFiles(Array.from(event.target.files || []))} />
        </Button>
        <Typography variant="body2" color="text.secondary" sx={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {selectedFiles.length ? selectedFiles.map((file) => `${file.name}（${formatBytes(file.size)}）`).join('、') : `上传到 ${path}`}
        </Typography>
        {selectedFiles.length ? <Button size="small" onClick={() => { setSelectedFiles([]); if (fileInputRef.current) fileInputRef.current.value = ''; }} disabled={uploadBusy}>清除</Button> : null}
        <Button size="small" variant="contained" disabled={!selectedFiles.length || uploadBusy} onClick={() => uploadFiles(selectedFiles)}>上传</Button>
      </Stack>
      {uploadProgress !== null ? <LinearProgress variant="determinate" value={uploadProgress} /> : null}
      {uploadStatus ? <Typography variant="body2" sx={{ px: 1.5, py: 1 }} role="status">{uploadStatus}</Typography> : null}
      {status.message ? <Alert severity={status.severity} sx={{ mx: 1.5, mb: 1.5 }} role="status">{status.message}</Alert> : null}

      <TableContainer sx={{ borderTop: 1, borderColor: 'divider' }}>
        <Table size="small" sx={{ minWidth: 760 }}>
          <TableHead><TableRow><TableCell width={90}>类型</TableCell><TableCell>名称</TableCell><TableCell width={110}>大小</TableCell><TableCell align="right" width={340}>操作</TableCell></TableRow></TableHead>
          <TableBody>
            {!loading && !entries.length ? <TableRow><TableCell colSpan={4} align="center" sx={{ py: 5, color: status.severity === 'error' ? 'error.main' : 'text.secondary' }}>{status.severity === 'error' ? '无法读取当前目录，请检查连接后重试' : '目录为空'}</TableCell></TableRow> : null}
            {entries.map((entry) => {
              const entryPath = joinRemotePath(path, entry.name);
              const directory = entry.kind === 'd';
              const downloadKey = `${directory ? 'directory' : 'file'}:${entryPath}`;
              return (
                <TableRow key={`${entry.kind}:${entry.name}`} hover>
                  <TableCell>{directory ? '目录' : entry.kind === 'l' ? '链接' : '文件'}</TableCell>
                  <TableCell sx={{ fontFamily: monoFont, fontWeight: 600, maxWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={entry.name}>{entry.name}</TableCell>
                  <TableCell>{directory ? '—' : formatBytes(entry.size)}</TableCell>
                  <TableCell align="right">
                    <Stack direction="row" spacing={0.75} sx={{ justifyContent: 'flex-end' }}>
                      {directory ? <Button size="small" variant="outlined" onClick={() => loadFiles(entryPath)}>打开</Button> : null}
                      <Button size="small" variant="outlined" disabled={downloadBusy.has(downloadKey)} onClick={() => downloadEntry(entryPath, directory ? 'directory' : 'file')}>{directory ? '下载压缩包' : '下载'}</Button>
                      <Button size="small" variant="outlined" onClick={() => setDialog({ type: 'rename', path: entryPath, name: entry.name })}>重命名</Button>
                      {(!directory || entry.empty) ? <Button size="small" color="error" variant="outlined" onClick={() => setDialog({ type: 'delete', path: entryPath, name: entry.name, directory })}>删除</Button> : null}
                    </Stack>
                  </TableCell>
                </TableRow>
              );
            })}
          </TableBody>
        </Table>
      </TableContainer>

      <TextInputDialog open={dialog?.type === 'create'} title="新建目录" label="新建目录名称" onClose={() => setDialog(null)} onConfirm={createDirectory} />
      <TextInputDialog open={dialog?.type === 'rename'} title={`重命名 “${dialog?.name || ''}”`} label="新名称" initialValue={dialog?.name || ''} onClose={() => setDialog(null)} onConfirm={renameEntry} />
      <ConfirmDialog open={dialog?.type === 'delete'} danger title="删除远程文件" message={dialog?.type === 'delete' ? `确认删除${dialog.directory ? '空目录' : '文件'} ${dialog.name}？` : ''} onClose={() => setDialog(null)} onConfirm={deleteEntry} />
    </Paper>
  );
}
