import { Button, LinearProgress, Paper, Stack, Typography } from '@mui/material';
import { formatBytes } from '../../utils.js';

const phaseLabels = {
  queued: '排队中', detecting: '检测来源', packing: '打包', uploading: '上传中', downloading: '下载中',
  verifying: '校验', extracting: '解包', merging: '合并', cancelling: '正在取消', cleaning: '清理临时文件',
  done: '完成', cancelled: '已取消', cleanup_error: '清理失败', error: '出错',
};
const directionPhaseLabels = {
  upload: {
    ...phaseLabels,
    detecting: '检测上传来源', verifying: '校验上传来源', packing: '打包上传内容', uploading: '上传中',
    done: '上传完成', cancelled: '上传已取消', error: '上传失败',
  },
  download: {
    ...phaseLabels,
    downloading: '下载中', verifying: '校验下载内容', merging: '写入目标',
    done: '下载完成', cancelled: '下载已取消', error: '下载失败',
  },
};

function progressColor(task) {
  if (task.status === 'error' || task.phase === 'cleanup_error') return 'error';
  if (task.status === 'cancelled') return 'warning';
  if (task.status === 'done') return 'success';
  return 'primary';
}

function progressText(task) {
  const upload = task.direction === 'upload';
  const progress = task.progress && typeof task.progress === 'object' ? task.progress : {};
  const bytes = Number.isFinite(progress.bytes) && progress.bytes >= 0 ? progress.bytes : 0;
  const total = Number.isFinite(progress.total) && progress.total >= 0 ? progress.total : null;
  const reportedPercent = Number.isFinite(progress.percent) ? Math.min(100, Math.max(0, progress.percent)) : null;
  const percent = reportedPercent ?? (task.status === 'done' ? 100 : null);
  const speed = Number.isFinite(progress.speed) && progress.speed > 0 ? progress.speed : 0;

  if (upload) {
    const uploadBytes = Number.isFinite(task.statistics?.bytes) && task.statistics.bytes >= 0
      ? task.statistics.bytes
      : null;
    return {
      percent,
      detail: uploadBytes !== null
        ? `${task.status === 'done' ? '已上传' : '待上传'} ${formatBytes(uploadBytes)}`
        : '正在获取上传信息…',
    };
  }

  const byteText = total !== null
    ? `${formatBytes(bytes)} / ${formatBytes(total)}`
    : (bytes > 0 ? `已下载 ${formatBytes(bytes)}` : '正在获取下载信息…');
  return {
    percent,
    detail: speed > 0 && task.phase === 'downloading' ? `${byteText} · ${formatBytes(speed)}/s` : byteText,
  };
}

function TransferProgress({ task, busy, cancelling, onCancel }) {
  const direction = task.direction === 'upload' ? 'upload' : 'download';
  const actionLabel = direction === 'upload' ? '上传' : '下载';
  const labels = directionPhaseLabels[direction];
  const progress = progressText(task);
  const determinate = progress.percent !== null;
  const percentLabel = determinate
    ? `${Number.isInteger(progress.percent) ? progress.percent : progress.percent.toFixed(1)}%`
    : null;
  return (
    <Stack spacing={1.25}>
      <Stack direction="row" sx={{ alignItems: 'baseline', justifyContent: 'space-between', gap: 1 }}>
        <Typography variant="subtitle2">{actionLabel}进度</Typography>
        <Typography variant="body2" color={task.status === 'error' ? 'error' : 'text.secondary'}>
          {labels[task.phase] || task.message || task.status}
        </Typography>
      </Stack>
      <LinearProgress
        aria-label={`OSS ${actionLabel}进度`}
        variant={determinate ? 'determinate' : 'indeterminate'}
        value={determinate ? progress.percent : undefined}
        color={progressColor(task)}
        sx={{ height: 10, borderRadius: 999, bgcolor: 'action.hover', '& .MuiLinearProgress-bar': { borderRadius: 999 } }}
      />
      <Stack direction="row" sx={{ justifyContent: 'space-between', alignItems: 'center', gap: 1 }}>
        <Typography variant="body2" color="text.secondary" sx={{ overflowWrap: 'anywhere' }}>
          {task.message || labels[task.phase] || `正在${actionLabel}…`}
        </Typography>
        <Stack direction="row" spacing={1} sx={{ flex: '0 0 auto', alignItems: 'baseline' }}>
          <Typography variant="body2" color="text.secondary">{progress.detail}</Typography>
          {percentLabel ? <Typography variant="body2" sx={{ fontWeight: 700, minWidth: 42, textAlign: 'right' }}>{percentLabel}</Typography> : null}
        </Stack>
      </Stack>
      {busy ? (
        <Button size="small" color="error" variant="outlined" sx={{ alignSelf: 'flex-start' }} disabled={cancelling} onClick={onCancel}>
          取消{actionLabel}
        </Button>
      ) : null}
    </Stack>
  );
}

export default function OssTaskPanel({ task, activeSide, busy, cancelling, onCancel }) {
  if (!task) return null;
  return (
    <Paper
      variant="outlined"
      hidden={task.side !== activeSide}
      aria-live="polite"
      sx={{ p: 1.5, bgcolor: 'background.default', '&[hidden]': { display: 'none' } }}
    >
      <TransferProgress task={task} busy={busy} cancelling={cancelling} onCancel={onCancel} />
    </Paper>
  );
}
