import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  List,
  ListItemButton,
  ListItemText,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import { api, jsonOptions, podUrl } from '../../api.js';
import { monoFont } from '../../theme.js';
import { joinRemotePath, parentPath } from '../../utils.js';

function defaultLocalPath(root, pod, remotePath) {
  const sub = remotePath === '/' || remotePath === ''
    ? 'root_fs'
    : remotePath.replace(/^\/+/, '').replace(/\/+$/, '').replace(/\//g, '_');
  return `${root}/${pod}/${sub}`;
}

export default function MountDialog({ open, pod, localMountRoot, onClose, onMount }) {
  const [path, setPath] = useState('/');
  const [directories, setDirectories] = useState([]);
  const [localPath, setLocalPath] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const loadToken = useRef(0);
  const localPathEdited = useRef(false);

  const loadDirectories = useCallback(async (requestedPath) => {
    if (!pod) return;
    const token = ++loadToken.current;
    setLoading(true);
    setMessage('');
    try {
      const data = await api(`${podUrl(pod, '/files')}?path=${encodeURIComponent(requestedPath)}`);
      if (token !== loadToken.current) return;
      setPath(data.path);
      setDirectories((data.entries || []).filter((entry) => entry.kind === 'd'));
      if (!localPathEdited.current) setLocalPath(defaultLocalPath(localMountRoot, pod, data.path));
    } catch (error) {
      if (token === loadToken.current) setMessage(`读取目录失败：${error.message}`);
    } finally {
      if (token === loadToken.current) setLoading(false);
    }
  }, [localMountRoot, pod]);

  useEffect(() => {
    if (!open || !pod) {
      loadToken.current += 1;
      return undefined;
    }
    localPathEdited.current = false;
    setPath('/');
    setDirectories([]);
    setLocalPath(defaultLocalPath(localMountRoot, pod, '/'));
    setMessage('正在连接…');
    let cancelled = false;
    (async () => {
      try {
        await api(podUrl(pod, '/tunnel'), jsonOptions('POST'));
      } catch (_) { /* The file request below reports a useful connection error. */ }
      if (!cancelled) await loadDirectories('/');
    })();
    return () => { cancelled = true; loadToken.current += 1; };
  }, [open, pod, localMountRoot, loadDirectories]);

  const browseLocal = async () => {
    try {
      const data = await api('/api/local-mount/pick', { method: 'POST' });
      if (data.path) {
        localPathEdited.current = true;
        setLocalPath(data.path);
      }
    } catch (_) { /* Native picker cancellation and failures were silent in the old UI. */ }
  };

  const confirm = () => {
    const selectedPod = pod;
    const remotePath = path;
    const destination = localPath.trim();
    onClose();
    onMount(selectedPod, remotePath, destination);
  };

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>选择挂载目录 — {pod}</DialogTitle>
      <DialogContent dividers>
        <Typography variant="body2" color="text.secondary" sx={{ fontFamily: monoFont, mb: 1 }}>{path}</Typography>
        {message ? <Alert severity={message === '正在连接…' ? 'info' : 'error'} sx={{ mb: 1 }}>{message}</Alert> : null}
        <Box sx={{ minHeight: 220, maxHeight: 360, overflow: 'auto', border: 1, borderColor: 'divider', borderRadius: 1 }}>
          <List dense disablePadding>
            {directories.map((entry) => (
              <ListItemButton key={entry.name} onClick={() => loadDirectories(joinRemotePath(path, entry.name))}>
                <ListItemText primary={`${entry.name}/`} primaryTypographyProps={{ fontFamily: monoFont }} />
              </ListItemButton>
            ))}
          </List>
          {!loading && !directories.length && !message ? <Typography color="text.secondary" align="center" sx={{ py: 5 }}>没有子目录</Typography> : null}
        </Box>
        <Stack spacing={1} sx={{ mt: 2 }}>
          <Typography component="label" htmlFor="mount-local-path" variant="body2">本地挂载位置</Typography>
          <Stack direction="row" spacing={1}>
            <TextField id="mount-local-path" fullWidth value={localPath} onChange={(event) => { localPathEdited.current = true; setLocalPath(event.target.value); }} placeholder="留空使用默认路径" sx={{ '& input': { fontFamily: monoFont } }} />
            <Button variant="outlined" onClick={browseLocal}>选择</Button>
          </Stack>
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>关闭</Button>
        <Button variant="outlined" disabled={path === '/' || loading} onClick={() => loadDirectories(parentPath(path))}>上级</Button>
        <Button variant="contained" disabled={loading || !!message} onClick={confirm}>挂载此目录</Button>
      </DialogActions>
    </Dialog>
  );
}
