export function normalizeDetail(detail) {
  if (Array.isArray(detail)) {
    return detail.map((item) => item?.msg || JSON.stringify(item)).join('；');
  }
  if (detail && typeof detail === 'object') {
    return detail.message || JSON.stringify(detail);
  }
  return detail;
}

export async function api(url, options = {}) {
  const response = await fetch(url, options);
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    const originalDetail = data.detail;
    const detail = normalizeDetail(originalDetail);
    const error = new Error(detail || '请求失败');
    error.status = response.status;
    error.code = originalDetail && typeof originalDetail === 'object' && !Array.isArray(originalDetail)
      ? originalDetail.code || null
      : null;
    error.detail = originalDetail;
    throw error;
  }
  return data;
}

export function jsonOptions(method, body = {}) {
  return {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  };
}

export function podUrl(name, suffix = '') {
  return `/api/pods/${encodeURIComponent(name)}${suffix}`;
}
