import {
  Alert,
  Autocomplete,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import { api, jsonOptions, podUrl } from '../../api.js';
import { monoFont } from '../../theme.js';
import { ConfirmDialog } from '../../components/Dialogs.jsx';
import ReadinessAlerts from '../../components/ReadinessAlerts.jsx';
import StatusBadge from '../../components/StatusBadge.jsx';
import MountDialog from '../mount/MountDialog.jsx';

export default function PodManagement({ visible, config, dependencies, readinessError, onReadinessRefresh, connectedPod, onConnect, onDisconnect, onUserChange }) {
  const defaults = config?.defaults || {};
  const [form, setForm] = useState({ type: 'a3', image: '', card: 16, user: '', name: '' });
  const [creating, setCreating] = useState(false);
  const [installingItask, setInstallingItask] = useState(false);
  const [itaskInstallError, setItaskInstallError] = useState('');
  const [message, setMessage] = useState({ text: '', severity: 'info' });
  const [pods, setPods] = useState([]);
  const [listStatus, setListStatus] = useState('加载中...');
  const [listError, setListError] = useState('');
  const [actionError, setActionError] = useState('');
  const [busyAction, setBusyAction] = useState('');
  const [confirm, setConfirm] = useState(null);
  const [mountPod, setMountPod] = useState(null);
  const [podDetails, setPodDetails] = useState(null);
  const refreshToken = useRef(0);
  const nasPollToken = useRef(0);
  const detailsToken = useRef(0);

  useEffect(() => {
    if (!config) return;
    const user = defaults.user || '';
    setForm({
      type: defaults.type || 'a3',
      image: defaults.image || '',
      card: Number(defaults.card ?? 16),
      user,
      name: user ? `${user}-itask` : '',
    });
    onUserChange(user);
  }, [config, defaults.card, defaults.image, defaults.type, defaults.user, onUserChange]);

  const refreshPods = useCallback(async () => {
    const token = ++refreshToken.current;
    try {
      const data = await api('/api/pods');
      if (token !== refreshToken.current) return;
      if (data.warning) {
        setPods([]);
        setListStatus('itask 不可用');
        setListError(String(data.warning));
        return;
      }
      const enriched = await Promise.all((data.pods || []).map(async (pod) => {
        try {
          const localMount = await api(podUrl(pod.name, '/local-mount'));
          return { ...pod, localMount };
        } catch (error) {
          return { ...pod, localMount: { mounts: [], error: error.message } };
        }
      }));
      if (token !== refreshToken.current) return;
      setPods(enriched);
      setListStatus(`${enriched.length} 个 Pod`);
      setListError('');
    } catch (error) {
      if (token !== refreshToken.current) return;
      setPods([]);
      setListStatus('itask 不可用');
      setListError(error.message);
    }
  }, []);

  useEffect(() => {
    if (!visible) return undefined;
    refreshPods();
    const interval = window.setInterval(() => {
      if (document.visibilityState === 'visible') refreshPods();
    }, 15000);
    const visibility = () => {
      if (document.visibilityState === 'visible') refreshPods();
    };
    document.addEventListener('visibilitychange', visibility);
    return () => {
      window.clearInterval(interval);
      document.removeEventListener('visibilitychange', visibility);
      refreshToken.current += 1;
    };
  }, [visible, refreshPods]);

  useEffect(() => () => { nasPollToken.current += 1; refreshToken.current += 1; }, []);

  const monitorMount = (name) => {
    const token = ++nasPollToken.current;
    const check = async () => {
      if (token !== nasPollToken.current) return;
      try {
        const status = await api(podUrl(name, '/mount-status'));
        if (token !== nasPollToken.current) return;
        if (status.status === 'ready') {
          setMessage({ text: `${name} 的 NAS 挂载完成`, severity: 'success' });
          return;
        }
        if (status.status === 'error') {
          setMessage({ text: `${name} 自动挂载失败：${status.message}`, severity: 'error' });
          return;
        }
        setMessage({ text: `${name} 已创建，${status.message || '正在挂载 NAS'}...`, severity: 'info' });
        window.setTimeout(check, 3000);
      } catch (_) {
        if (token === nasPollToken.current) window.setTimeout(check, 5000);
      }
    };
    check();
  };

  const updateUser = (user) => {
    setForm((current) => ({ ...current, user, name: user ? `${user}-itask` : '' }));
    onUserChange(user);
  };

  const installItask = async () => {
    if (installingItask) return;
    setInstallingItask(true);
    setItaskInstallError('');
    try {
      try {
        await api('/api/itask/install', {
          method: 'POST',
          headers: { 'X-Itask-GUI-Request': 'itask-install' },
        });
      } catch (error) {
        setItaskInstallError(error.message);
        await onReadinessRefresh().catch(() => {});
        return;
      }

      setMessage({ text: 'itask 已安装并验证通过', severity: 'success' });
      try {
        await onReadinessRefresh();
      } catch (error) {
        setMessage({ text: `itask 已安装，但状态刷新失败：${error.message}`, severity: 'warning' });
      }
      await refreshPods();
    } finally {
      setInstallingItask(false);
    }
  };

  const createPod = async (event) => {
    event.preventDefault();
    setCreating(true);
    setMessage({ text: '正在申请容器...', severity: 'info' });
    try {
      const data = await api('/api/pods', jsonOptions('POST', { ...form, card: Number(form.card) }));
      setMessage({ text: `Pod ${data.name} 已创建，正在等待调度；就绪后自动挂载 NAS`, severity: 'success' });
      await refreshPods().catch(() => {});
      monitorMount(data.name);
    } catch (error) {
      setMessage({ text: `申请失败：${error.message}`, severity: 'error' });
    } finally {
      setCreating(false);
    }
  };

  const showPodDetails = async (name) => {
    const token = ++detailsToken.current;
    setPodDetails({ name, loading: true, text: '', error: '' });
    try {
      const data = await api(podUrl(name, '/details'));
      if (token !== detailsToken.current) return;
      const text = [data.details, data.warning].filter(Boolean).join('\n\n');
      setPodDetails({ name, loading: false, text: text || '没有可用的任务详情', error: '' });
    } catch (error) {
      if (token === detailsToken.current) setPodDetails({ name, loading: false, text: '', error: error.message });
    }
  };

  const closePodDetails = () => {
    detailsToken.current += 1;
    setPodDetails(null);
  };

  const connect = async (name) => {
    setBusyAction(`connect:${name}`);
    setActionError('');
    try {
      const tunnel = await api(podUrl(name, '/tunnel'), jsonOptions('POST'));
      onConnect(name, tunnel);
    } catch (error) {
      setActionError(`连接失败：${error.message}`);
    } finally {
      setBusyAction('');
    }
  };

  const deletePod = async () => {
    const name = confirm?.pod;
    setConfirm(null);
    if (!name) return;
    setBusyAction(`delete:${name}`);
    setActionError('');
    try {
      await api(podUrl(name), { method: 'DELETE' });
      if (connectedPod === name) onDisconnect();
      await refreshPods();
    } catch (error) {
      setActionError(`删除失败：${error.message}`);
    } finally {
      setBusyAction('');
    }
  };

  const mount = async (name, remotePath, localPath) => {
    setBusyAction(`mount:${name}`);
    setActionError('');
    try {
      await api(podUrl(name, '/local-mount'), jsonOptions('POST', { remote_path: remotePath, local_path: localPath || '' }));
      await refreshPods();
    } catch (error) {
      setActionError(`挂载失败：${error.message}`);
    } finally {
      setBusyAction('');
    }
  };

  const unmount = async (name, remotePath, force = false) => {
    setBusyAction(`unmount:${name}:${remotePath}`);
    setActionError('');
    try {
      await api(`${podUrl(name, '/local-mount')}?remote_path=${encodeURIComponent(remotePath)}${force ? '&force=true' : ''}`, { method: 'DELETE' });
      await refreshPods();
    } catch (error) {
      if (!force) {
        setConfirm({ type: 'force-unmount', pod: name, remotePath, message: `卸载失败：${error.message}\n是否强制卸载？` });
      } else {
        setActionError(`强制卸载失败：${error.message}`);
      }
    } finally {
      setBusyAction('');
    }
  };

  const itaskItem = dependencies.itask;
  const dependenciesCurrent = !readinessError;
  const sshReady = dependenciesCurrent && dependencies.ssh?.ready === true;
  const sshfsReady = dependenciesCurrent && dependencies.sshfs?.ready === true;
  const canInstallItask = dependenciesCurrent
    && itaskItem?.state === 'missing'
    && itaskItem?.installed === false
    && itaskItem?.installable === true;
  const itaskReady = dependenciesCurrent && itaskItem?.ready === true;
  const itaskStatus = readinessError
    ? { label: 'itask 状态检测失败', tone: 'warning' }
    : !itaskItem
      ? { label: 'itask 检查中', tone: 'neutral' }
      : installingItask
        ? { label: '正在下载并安装 itask…', tone: 'neutral' }
        : itaskItem.ready
          ? { label: 'itask 已安装且可用', tone: 'success' }
          : canInstallItask
            ? { label: itaskInstallError ? '安装失败，点击重试' : '未安装 itask，点击安装', tone: itaskInstallError ? 'error' : 'warning' }
            : itaskItem.installed
              ? { label: 'itask 已安装但不可用', tone: 'error' }
              : { label: 'itask 未安装', tone: 'error' };

  return (
    <Stack spacing={2}>
      <Paper variant="outlined" sx={{ p: 2 }}>
        <Stack spacing={1.5} sx={{ mb: 2 }}>
          <Typography variant="h6">申请容器</Typography>
          <Stack direction="row" useFlexGap flexWrap="wrap" spacing={1}>
            <StatusBadge
              tone={itaskStatus.tone}
              label={itaskStatus.label}
              title={installingItask ? `正在安装 ${itaskItem?.artifact || 'itask'} 到 ${itaskItem?.install_target || '用户目录'}` : readinessError || itaskItem?.detail || ''}
              onClick={canInstallItask ? installItask : undefined}
              disabled={installingItask}
            />
          </Stack>
        </Stack>
        <ReadinessAlerts items={canInstallItask ? [] : [dependencies.itask]} fallback={readinessError} />
        {itaskInstallError ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setItaskInstallError('')}>安装 itask 失败：{itaskInstallError}</Alert> : null}
        <Box component="form" onSubmit={createPod}>
          <Stack direction={{ xs: 'column', md: 'row' }} spacing={1.5} sx={{ alignItems: { md: 'flex-start' } }}>
            <FormControl sx={{ minWidth: 100 }}>
              <InputLabel id="pod-type-label">类型</InputLabel>
              <Select labelId="pod-type-label" label="类型" value={form.type} onChange={(event) => setForm((current) => ({ ...current, type: event.target.value }))}>
                <MenuItem value="a2">a2</MenuItem><MenuItem value="a3">a3</MenuItem>
              </Select>
            </FormControl>
            <Autocomplete
              freeSolo
              options={config?.images || []}
              value={form.image}
              onInputChange={(_, value) => setForm((current) => ({ ...current, image: value }))}
              renderInput={(params) => <TextField {...params} label="镜像" required />}
              sx={{ flex: 2, minWidth: 240 }}
            />
            <TextField label="卡数" value={form.card} InputProps={{ readOnly: true }} required sx={{ width: 95 }} />
            <Autocomplete
              freeSolo
              options={config?.users || []}
              value={form.user}
              onInputChange={(_, value) => updateUser(value)}
              renderInput={(params) => <TextField {...params} label="用户" required />}
              sx={{ flex: 1, minWidth: 150 }}
            />
            <TextField label="Pod 名称" value={form.name} InputProps={{ readOnly: true }} required sx={{ flex: 1, minWidth: 190, '& input': { fontFamily: monoFont } }} />
            <Button type="submit" variant="contained" disabled={creating || !itaskReady} sx={{ minWidth: 88 }}>申请</Button>
          </Stack>
        </Box>
        {message.text ? <Alert severity={message.severity} sx={{ mt: 1.5 }}>{message.text}</Alert> : null}
      </Paper>

      <Paper variant="outlined" sx={{ p: 2 }}>
        <Stack direction="row" sx={{ justifyContent: 'space-between', alignItems: 'baseline', mb: 1.5 }}>
          <Typography variant="h6">Pod 列表</Typography>
          <Typography variant="body2" color={listError ? 'error' : 'text.secondary'}>{listStatus}</Typography>
        </Stack>
        <ReadinessAlerts items={[dependencies.ssh, dependencies.sshfs]} />
        {listError ? <Alert severity="error" sx={{ mb: 1.5 }}>{listError}</Alert> : null}
        {actionError ? <Alert severity="error" sx={{ mb: 1.5 }} onClose={() => setActionError('')}>{actionError}</Alert> : null}
        <Stack spacing={1}>
          {pods.map((pod) => {
            const lifecycleStatus = String(pod.pod_status || pod.status || 'unknown');
            const normalizedStatus = lifecycleStatus.toLowerCase();
            const podReady = normalizedStatus === 'running' || normalizedStatus === 'ready';
            const podPending = normalizedStatus === 'pending';
            return (
            <Card key={pod.name} variant="outlined">
              <CardContent sx={{ p: '12px !important' }}>
                <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ justifyContent: 'space-between', alignItems: { md: 'center' } }}>
                  <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0 }}>
                    <Typography sx={{ fontFamily: monoFont, fontWeight: 700, overflow: 'hidden', textOverflow: 'ellipsis' }}>{pod.name}</Typography>
                    <Chip size="small" label={lifecycleStatus} color={podPending ? 'warning' : podReady ? 'success' : 'default'} variant="outlined" />
                  </Stack>
                  <Stack direction="row" spacing={0.75}>
                    <Button size="small" variant="outlined" color={podPending ? 'warning' : 'primary'} disabled={!!busyAction} onClick={() => showPodDetails(pod.name)}>{podPending ? '查看原因' : '详情'}</Button>
                    <Button size="small" variant="contained" disabled={!!busyAction || !itaskReady || !sshReady || !podReady} title={podReady ? '' : `Pod 当前状态为 ${lifecycleStatus}`} onClick={() => connect(pod.name)}>连接</Button>
                    <Button size="small" variant="outlined" disabled={!!busyAction || !itaskReady || !sshReady || !sshfsReady || !podReady} title={!podReady ? `Pod 当前状态为 ${lifecycleStatus}` : sshfsReady ? '' : '未安装 sshfs / macFUSE，请按 README 完成安装'} onClick={() => setMountPod(pod.name)}>本机挂载</Button>
                    <Button size="small" variant="outlined" color="error" disabled={!!busyAction || !itaskReady} onClick={() => setConfirm({ type: 'delete', pod: pod.name })}>删除</Button>
                  </Stack>
                </Stack>
                {podPending ? <Alert severity="warning" sx={{ mt: 1 }}>Pod 正在等待集群调度。点击“查看原因”查看资源不足、节点约束和事件详情。</Alert> : null}
                {pod.localMount?.error ? <Typography variant="body2" color="error" sx={{ mt: 1 }}>读取本机挂载状态失败：{pod.localMount.error}</Typography> : null}
                {(pod.localMount?.mounts || []).map((mountState) => (
                  <Stack key={mountState.remote_path} direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ mt: 1, pt: 1, borderTop: 1, borderColor: 'divider', justifyContent: 'space-between', alignItems: { md: 'center' } }}>
                    <Typography variant="body2" color="text.secondary" sx={{ fontFamily: monoFont, overflowWrap: 'anywhere' }}>
                      {mountState.remote_path} → {mountState.local_path}{mountState.mounted === false ? '（未挂载）' : ''}
                    </Typography>
                    <Stack direction="row" spacing={0.75}>
                      <Button size="small" variant="outlined" onClick={() => api(`/api/local-mount/open?path=${encodeURIComponent(mountState.local_path)}`, { method: 'POST' }).catch(() => {})}>打开</Button>
                      <Button size="small" variant="outlined" disabled={!!busyAction} onClick={() => unmount(pod.name, mountState.remote_path)}>卸载</Button>
                    </Stack>
                  </Stack>
                ))}
              </CardContent>
            </Card>
            );
          })}
          {!pods.length && !listError ? <Typography align="center" color="text.secondary" sx={{ py: 4 }}>没有 Pod</Typography> : null}
        </Stack>
      </Paper>

      <Dialog open={!!podDetails} onClose={closePodDetails} fullWidth maxWidth="lg">
        <DialogTitle>Pod 详情与调度诊断 — {podDetails?.name || ''}</DialogTitle>
        <DialogContent dividers>
          {podDetails?.loading ? (
            <Stack direction="row" spacing={1} sx={{ alignItems: 'center', py: 3, justifyContent: 'center' }}>
              <CircularProgress size={22} />
              <Typography color="text.secondary">正在读取 itask describe…</Typography>
            </Stack>
          ) : null}
          {podDetails?.error ? <Alert severity="error">读取详情失败：{podDetails.error}</Alert> : null}
          {podDetails?.text ? (
            <Box component="pre" sx={{ m: 0, p: 1.5, maxHeight: '65vh', overflow: 'auto', whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', bgcolor: 'background.default', borderRadius: 1, fontFamily: monoFont, fontSize: 13 }}>
              {podDetails.text}
            </Box>
          ) : null}
        </DialogContent>
        <DialogActions>
          <Button disabled={!podDetails?.name || podDetails?.loading} onClick={() => showPodDetails(podDetails.name)}>刷新</Button>
          <Button variant="contained" onClick={closePodDetails}>关闭</Button>
        </DialogActions>
      </Dialog>
      <MountDialog open={!!mountPod} pod={mountPod} localMountRoot={config?.local_mount_root || ''} onClose={() => setMountPod(null)} onMount={mount} />
      <ConfirmDialog open={confirm?.type === 'delete'} danger title="删除 Pod" message={confirm?.type === 'delete' ? `确认删除 ${confirm.pod}？` : ''} onClose={() => setConfirm(null)} onConfirm={deletePod} />
      <ConfirmDialog open={confirm?.type === 'force-unmount'} danger title="强制卸载" message={confirm?.type === 'force-unmount' ? confirm.message : ''} confirmText="强制卸载" onClose={() => setConfirm(null)} onConfirm={() => { const target = confirm; setConfirm(null); unmount(target.pod, target.remotePath, true); }} />
    </Stack>
  );
}
