import { Box, Button, Paper, Stack, Typography } from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { api } from '../../api.js';
import FileBrowser from '../files/FileBrowser.jsx';
import PodManagement from '../pods/PodManagement.jsx';
import TerminalPanel from '../terminal/TerminalPanel.jsx';

export default function ItaskPage({ active, connection, onConnectionChange, onDefaultUserChange, onRequestItask }) {
  const [config, setConfig] = useState(null);
  const [dependencies, setDependencies] = useState({});
  const [readinessError, setReadinessError] = useState('');
  const [initializationError, setInitializationError] = useState('');
  const [initialized, setInitialized] = useState(false);
  const [view, setView] = useState('list');
  const initializationToken = useRef(0);

  useEffect(() => {
    const token = ++initializationToken.current;
    (async () => {
      try {
        const nextConfig = await api('/api/config');
        if (token !== initializationToken.current) return;
        setConfig(nextConfig);
        try {
          const readiness = await api('/api/readiness');
          if (token !== initializationToken.current) return;
          setDependencies(Object.fromEntries((readiness.items || []).map((item) => [item.id, item])));
          setReadinessError('');
        } catch (error) {
          if (token === initializationToken.current) setReadinessError(`依赖检测失败：${error.message}`);
        }
      } catch (error) {
        if (token === initializationToken.current) setInitializationError(error.message);
      } finally {
        if (token === initializationToken.current) setInitialized(true);
      }
    })();
    return () => { initializationToken.current += 1; };
  }, []);

  const refreshReadiness = async () => {
    try {
      const readiness = await api('/api/readiness');
      setDependencies(Object.fromEntries((readiness.items || []).map((item) => [item.id, item])));
      setReadinessError('');
      return readiness;
    } catch (error) {
      setDependencies({});
      setReadinessError(`依赖检测失败：${error.message}`);
      throw error;
    }
  };

  const connect = (pod, tunnel) => {
    onConnectionChange({ pod, tunnelLabel: `隧道 127.0.0.1:${tunnel.port}` });
    setView('workspace');
    onRequestItask();
  };

  const disconnect = () => {
    onConnectionChange(null);
    setView('list');
    onRequestItask();
  };

  return (
    <>
      {connection ? (
        <Paper variant="outlined" sx={{ mb: 2, px: 2, minHeight: 48, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
            <Box sx={{ width: 9, height: 9, borderRadius: '50%', bgcolor: 'success.main' }} />
            <Typography sx={{ fontWeight: 650 }}>{connection.pod}</Typography>
          </Stack>
          <Stack direction="row" spacing={1}>
            <Button size="small" variant="outlined" onClick={() => setView((current) => current === 'workspace' ? 'list' : 'workspace')}>
              {view === 'workspace' ? '返回列表' : '返回工作区'}
            </Button>
            <Button size="small" variant="outlined" color="error" onClick={disconnect}>断开</Button>
          </Stack>
        </Paper>
      ) : null}

      <Box sx={{ display: active ? 'block' : 'none' }}>
        {initializationError ? <Paper variant="outlined" sx={{ p: 2, color: 'error.main' }}>{initializationError}</Paper> : null}
        <Box sx={{ display: view === 'list' ? 'block' : 'none' }}>
          <PodManagement
            visible={active && view === 'list' && initialized && !initializationError}
            config={config}
            dependencies={dependencies}
            readinessError={readinessError}
            onReadinessRefresh={refreshReadiness}
            connectedPod={connection?.pod || null}
            onConnect={connect}
            onDisconnect={disconnect}
            onUserChange={onDefaultUserChange}
          />
        </Box>
        {connection ? (
          <Stack spacing={2} sx={{ display: view === 'workspace' ? 'flex' : 'none' }}>
            <FileBrowser pod={connection.pod} remoteRoot={config?.remote_root || '/root'} />
            <TerminalPanel pod={connection.pod} tunnelLabel={connection.tunnelLabel} visible={active && view === 'workspace'} />
          </Stack>
        ) : null}
      </Box>
    </>
  );
}
