export function sourceName(path) {
  return String(path || '').replace(/\/+$/, '').split('/').pop() || '';
}

export function joinPath(directory, name) {
  const normalized = String(directory || '').replace(/\/+$/, '');
  return `${normalized || '/'}/${name}`.replace(/^\/\//, '/');
}

export function normalizeOssKey(value) {
  return String(value || '').replace(/^\/+/, '');
}

export function uploadKey(path, sourceKind, packageUpload) {
  const name = sourceName(path);
  if (!name) return '';
  if (sourceKind === 'file') return name;
  if (sourceKind === 'directory') return packageUpload ? `${name}.tar` : `${name}/`;
  return '';
}

export function objectContext(side, user, prefix, pod) {
  return `${side}:${side === 'remote' ? (pod || '') : ''}:${user}:${prefix}`;
}

export function objectEndpoint(side, user, prefix, pod) {
  const query = `user=${encodeURIComponent(user)}&prefix=${encodeURIComponent(prefix)}`;
  return side === 'local'
    ? `/api/oss/objects?${query}`
    : `/api/pods/${encodeURIComponent(pod)}/oss/objects?${query}`;
}

export function ossBreadcrumbs(prefix) {
  const parts = String(prefix || '').split('/').filter(Boolean);
  let current = '';
  return [{ label: '根目录', prefix: '' }, ...parts.map((part) => {
    current += `${part}/`;
    return { label: part, prefix: current };
  })];
}
