import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { api, jsonOptions } from '../../api.js';
import { monoFont } from '../../theme.js';
import StatusBadge from '../../components/StatusBadge.jsx';

export function readinessMessage(readiness) {
  if (!readiness?.config?.valid) return { text: '请先配置 OSS', severity: 'error' };
  if (!readiness.dependencies?.ossutil) return { text: '远端传输可用；本机传输需安装 ossutil', severity: 'info' };
  if (!readiness.capabilities?.directory_download) return { text: '文件与目录上传可用，本机目录下载需要 rsync', severity: 'info' };
  return { text: '本机与远端 OSS 凭据已就绪', severity: 'success' };
}

export default function OssConfigPanel({ readiness, onReadiness, onConfigured }) {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [replacing, setReplacing] = useState(false);
  const [loadingCredentials, setLoadingCredentials] = useState(false);
  const [accessKeyId, setAccessKeyId] = useState('');
  const [secret, setSecret] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [dialogMessage, setDialogMessage] = useState(null);
  const [panelMessage, setPanelMessage] = useState(null);
  const [installingOssutil, setInstallingOssutil] = useState(false);
  const [ossutilInstallError, setOssutilInstallError] = useState('');
  const credentialsRequest = useRef(null);
  const config = readiness?.config || {};
  const ossutilItem = readiness?.ossutil;
  const canInstallOssutil = ossutilItem?.state === 'missing'
    && ossutilItem?.installed === false
    && ossutilItem?.installable === true;
  const ossutilStatus = !readiness
    ? { label: 'ossutil：检查中', tone: 'neutral' }
    : installingOssutil
      ? { label: 'ossutil：正在下载并安装…', tone: 'neutral' }
      : (ossutilItem?.ready || (!ossutilItem && readiness.dependencies?.ossutil))
        ? { label: `ossutil：已安装 ${ossutilItem?.version || ''}`.trim(), tone: 'success' }
        : canInstallOssutil
          ? { label: ossutilInstallError ? 'ossutil：安装失败，点击重试' : 'ossutil：未安装，点击安装', tone: ossutilInstallError ? 'error' : 'warning' }
          : ossutilItem?.installed
            ? { label: 'ossutil：已安装但不可用', tone: 'error' }
            : { label: 'ossutil：未安装', tone: 'error' };

  const clearSensitiveState = () => {
    credentialsRequest.current?.abort();
    credentialsRequest.current = null;
    setAccessKeyId('');
    setSecret('');
    setLoadingCredentials(false);
    setDialogMessage(null);
  };

  const closeDialog = (force = false) => {
    if (submitting && !force) return;
    clearSensitiveState();
    setDialogOpen(false);
    setReplacing(false);
  };

  useEffect(() => () => credentialsRequest.current?.abort(), []);

  const openDialog = async () => {
    const shouldReplace = Boolean(config.exists);
    clearSensitiveState();
    setPanelMessage(null);
    setReplacing(shouldReplace);
    setDialogOpen(true);
    if (!shouldReplace) return;

    const controller = new AbortController();
    credentialsRequest.current = controller;
    setLoadingCredentials(true);
    try {
      const credentials = await api('/api/oss/config', {
        cache: 'no-store',
        signal: controller.signal,
        headers: { 'X-Itask-GUI-Request': 'oss-config-dialog' },
      });
      if (credentialsRequest.current !== controller) return;
      setAccessKeyId(credentials.access_key_id || '');
      setSecret(credentials.access_key_secret || '');
    } catch (error) {
      if (error.name === 'AbortError' || credentialsRequest.current !== controller) return;
      setDialogMessage({ text: `读取当前配置失败：${error.message}。可手动重新填写。`, severity: 'warning' });
    } finally {
      if (credentialsRequest.current === controller) {
        credentialsRequest.current = null;
        setLoadingCredentials(false);
      }
    }
  };

  const installOssutil = async () => {
    if (installingOssutil || !canInstallOssutil) return;
    setInstallingOssutil(true);
    setOssutilInstallError('');
    setPanelMessage({ text: '正在下载、校验并安装 ossutil…', severity: 'info' });
    try {
      await api('/api/ossutil/install', {
        method: 'POST',
        headers: { 'X-Itask-GUI-Request': 'ossutil-install' },
      });
      const refreshErrors = [];
      try {
        const refreshed = await api('/api/oss/readiness', { cache: 'no-store' });
        onReadiness(refreshed);
      } catch (error) {
        refreshErrors.push(error.message);
      }
      try { await api('/api/readiness', { cache: 'no-store' }); } catch (error) { refreshErrors.push(error.message); }
      onConfigured();
      setPanelMessage(refreshErrors.length
        ? { text: `ossutil 已安装，但环境状态刷新失败：${refreshErrors.join('；')}`, severity: 'warning' }
        : { text: 'ossutil 已安装并通过版本与完整性校验', severity: 'success' });
    } catch (error) {
      setOssutilInstallError(error.message);
      setPanelMessage({ text: `安装 ossutil 失败：${error.message}`, severity: 'error' });
      try {
        const refreshed = await api('/api/oss/readiness', { cache: 'no-store' });
        onReadiness(refreshed);
      } catch (_) { /* Keep the actionable installation error visible. */ }
    } finally {
      setInstallingOssutil(false);
    }
  };

  const submit = async (event) => {
    event.preventDefault();
    setSubmitting(true);
    setDialogMessage({ text: '正在保存配置...', severity: 'info' });
    try {
      const result = await api('/api/oss/config', jsonOptions('POST', {
        access_key_id: accessKeyId.trim(),
        access_key_secret: secret,
        replace_existing: replacing,
      }));
      onReadiness(result.readiness);
      const refreshErrors = [];
      try { await api('/api/readiness'); } catch (error) { refreshErrors.push(error.message); }
      try {
        const refreshed = await api('/api/oss/readiness');
        onReadiness(refreshed);
      } catch (error) {
        refreshErrors.push(error.message);
      }
      onConfigured();
      setSubmitting(false);
      closeDialog(true);
      setPanelMessage(refreshErrors.length
        ? { text: `配置已保存，但环境状态刷新失败：${refreshErrors.join('；')}`, severity: 'warning' }
        : { text: '配置已保存', severity: 'success' });
    } catch (error) {
      setSecret('');
      setDialogMessage({ text: `保存失败：${error.message}`, severity: 'error' });
      setSubmitting(false);
    }
  };

  return (
    <>
      <Paper variant="outlined" sx={{ p: 2 }}>
        <Stack spacing={1.5}>
          <Stack direction={{ xs: 'column', sm: 'row' }} sx={{ alignItems: { sm: 'center' }, justifyContent: 'space-between', gap: 1.5 }}>
            <Box>
              <Typography variant="subtitle1">OSS 配置</Typography>
            </Box>
            <Button variant="outlined" disabled={!readiness} onClick={openDialog} sx={{ alignSelf: { xs: 'flex-start', sm: 'center' } }}>
              配置
            </Button>
          </Stack>
          <Stack direction="row" useFlexGap flexWrap="wrap" spacing={1}>
            <StatusBadge
              label={ossutilStatus.label}
              tone={ossutilStatus.tone}
              title={installingOssutil
                ? `正在安装 ${ossutilItem?.version || 'ossutil v1.7.19'} 到 ${ossutilItem?.install_target || '用户目录'}`
                : ossutilInstallError || ossutilItem?.detail || '本机 OSS 传输工具状态'}
              onClick={canInstallOssutil ? installOssutil : undefined}
              disabled={installingOssutil}
            />
            <StatusBadge
              label={`OSS 配置：${!readiness ? '检查中' : config.valid ? '有效' : config.exists ? '无效' : '未配置'}`}
              tone={!readiness ? 'neutral' : config.valid ? 'success' : 'error'}
              title={config.detail || '正在检查 OSS 配置'}
            />
            <StatusBadge
              label={`rsync：${!readiness ? '检查中' : readiness.dependencies?.rsync ? '已安装' : '未安装（仅影响目录下载）'}`}
              tone={!readiness ? 'neutral' : readiness.dependencies?.rsync ? 'success' : 'warning'}
              title={readiness?.dependencies?.rsync ? '本机目录下载可用' : '未检测到 rsync；仅影响本机目录下载'}
            />
          </Stack>
          {panelMessage ? <Alert severity={panelMessage.severity} onClose={() => setPanelMessage(null)}>{panelMessage.text}</Alert> : null}
        </Stack>
      </Paper>

      <Dialog
        open={dialogOpen}
        onClose={() => closeDialog()}
        fullWidth
        maxWidth="sm"
        PaperProps={{ component: 'form', onSubmit: submit, autoComplete: 'off' }}
      >
        <DialogTitle>配置 OSS</DialogTitle>
        <DialogContent dividers>
          <Stack spacing={1.5}>
            <Typography variant="body2" color="text.secondary">
              配置文件：<Box component="code" sx={{ fontFamily: monoFont }}>{config.path || '~/.ossutilconfig'}</Box>
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Endpoint：<Box component="code" sx={{ fontFamily: monoFont }}>{config.endpoint || ''}</Box>
            </Typography>
            {loadingCredentials ? (
              <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minHeight: 40 }}>
                <CircularProgress size={20} />
                <Typography variant="body2" color="text.secondary">正在读取当前配置…</Typography>
              </Stack>
            ) : null}
            <TextField
              fullWidth
              autoFocus
              label="AccessKey ID"
              value={accessKeyId}
              onChange={(event) => setAccessKeyId(event.target.value)}
              disabled={loadingCredentials || submitting}
              required
              autoComplete="off"
            />
            <TextField
              fullWidth
              type="password"
              label="AccessKey Secret"
              value={secret}
              onChange={(event) => setSecret(event.target.value)}
              disabled={loadingCredentials || submitting}
              autoComplete="new-password"
              required
            />
            {dialogMessage ? <Alert severity={dialogMessage.severity}>{dialogMessage.text}</Alert> : null}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => closeDialog()} disabled={submitting}>取消</Button>
          <Button type="submit" variant="contained" disabled={loadingCredentials || submitting || !accessKeyId.trim() || !secret}>保存配置</Button>
        </DialogActions>
      </Dialog>
    </>
  );
}
