import { useCallback, useEffect, useMemo, useRef } from 'react';
import { api } from '../../api.js';
import { objectContext, objectEndpoint } from './ossUtils.js';

export default function useOssObjects() {
  const loadToken = useRef(0);
  const cache = useRef({ context: '', entries: [] });

  const invalidate = useCallback(() => {
    loadToken.current += 1;
    cache.current = { context: '', entries: [] };
  }, []);

  const load = useCallback(async (side, user, prefix, force = false, pod = null) => {
    const context = objectContext(side, user, prefix, pod);
    if (!force && cache.current.context === context) return cache.current.entries;
    const token = ++loadToken.current;
    const data = await api(objectEndpoint(side, user, prefix, pod));
    if (token !== loadToken.current) return null;
    const entries = Array.isArray(data.entries) ? data.entries : [];
    cache.current = { context, entries };
    return entries;
  }, []);

  useEffect(() => () => { loadToken.current += 1; }, []);

  return useMemo(() => ({ load, invalidate }), [load, invalidate]);
}
