import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../../api.js';

export default function useOssTask({ onUploadDone }) {
  const [task, setTask] = useState(null);
  const [busy, setBusy] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [status, setStatus] = useState(null);
  const [lastProgressPhase, setLastProgressPhase] = useState('queued');
  const pollToken = useRef(0);
  const timers = useRef(new Set());
  const uploadDoneRef = useRef(onUploadDone);
  uploadDoneRef.current = onUploadDone;

  const schedule = useCallback((callback, delay) => {
    const timer = window.setTimeout(() => {
      timers.current.delete(timer);
      callback();
    }, delay);
    timers.current.add(timer);
  }, []);

  const clearTask = useCallback((taskId, delay = 0) => {
    const clear = () => setTask((current) => (!current || current.task_id === taskId ? null : current));
    setBusy(false);
    if (delay) schedule(clear, delay);
    else clear();
  }, [schedule]);

  const monitor = useCallback((taskId) => {
    const token = ++pollToken.current;
    let failures = 0;
    let lastPhase = 'queued';
    const check = async () => {
      if (token !== pollToken.current) return;
      try {
        const nextTask = await api(`/api/oss/tasks/${encodeURIComponent(taskId)}`);
        if (token !== pollToken.current) return;
        failures = 0;
        if (!['cancelled', 'cleanup_error', 'error'].includes(nextTask.phase) && nextTask.phase) {
          lastPhase = nextTask.phase;
          setLastProgressPhase(nextTask.phase);
        } else {
          setLastProgressPhase(lastPhase);
        }
        setTask(nextTask);
        setStatus({ text: nextTask.message || nextTask.status, severity: ['error', 'cleanup_error'].includes(nextTask.status) ? 'error' : 'info' });
        if (['queued', 'running'].includes(nextTask.status)) {
          schedule(check, nextTask.direction === 'download' ? 750 : 2500);
          return;
        }
        if (nextTask.status === 'done' && nextTask.direction === 'upload') uploadDoneRef.current?.(nextTask);
        clearTask(taskId, 3000);
      } catch (error) {
        if (token !== pollToken.current) return;
        if (error.status === 404) {
          clearTask(taskId);
          setStatus({ text: 'OSS 任务已不存在', severity: 'error' });
          return;
        }
        failures += 1;
        setBusy(true);
        setStatus({ text: `任务状态读取失败，正在第 ${failures} 次重试：${error.message}`, severity: 'error' });
        schedule(check, Math.min(2500 * (2 ** Math.min(failures, 4)), 30000));
      }
    };
    check();
  }, [clearTask, schedule]);

  const acceptTask = useCallback((nextTask) => {
    setTask(nextTask);
    setBusy(true);
    setLastProgressPhase('queued');
    setStatus({ text: nextTask.message || '传输任务已排队', severity: 'info' });
    monitor(nextTask.task_id);
  }, [monitor]);

  const recover = useCallback(async () => {
    try {
      const active = await api('/api/oss/active-task');
      if (active.task?.task_id) acceptTask(active.task);
    } catch (error) {
      setStatus({ text: `活动任务恢复失败：${error.message}`, severity: 'error' });
    }
  }, [acceptTask]);

  const cancel = useCallback(async () => {
    if (!task?.task_id || cancelling) return;
    setCancelling(true);
    setStatus({ text: '正在取消任务并终止远端进程…', severity: 'info' });
    try {
      await api(`/api/oss/tasks/${encodeURIComponent(task.task_id)}`, { method: 'DELETE' });
    } catch (error) {
      setStatus({ text: `取消失败：${error.message}`, severity: 'error' });
    } finally {
      setCancelling(false);
    }
  }, [cancelling, task]);

  useEffect(() => () => {
    pollToken.current += 1;
    timers.current.forEach((timer) => window.clearTimeout(timer));
    timers.current.clear();
  }, []);

  return { task, busy, cancelling, status, lastProgressPhase, acceptTask, recover, cancel };
}
