import { Container, Paper, Tab, Tabs } from '@mui/material';
import { useState } from 'react';
import ItaskPage from './features/itask/ItaskPage.jsx';
import OssPage from './features/oss/OssPage.jsx';

export default function App() {
  const [page, setPage] = useState('itask');
  const [connection, setConnection] = useState(null);
  const [ossUser, setOssUser] = useState('');

  return (
    <Container
      maxWidth={false}
      sx={{
        maxWidth: 1920,
        mx: 'auto',
        px: { xs: 2, sm: 3, lg: 4 },
        py: { xs: 2, lg: 3 },
      }}
    >
      <Paper variant="outlined" sx={{ overflow: 'hidden', mb: 2 }}>
        <Tabs
          value={page}
          onChange={(_, value) => setPage(value)}
          aria-label="主要功能"
          sx={{ px: 2 }}
        >
          <Tab value="itask" label="itask" />
          <Tab value="oss" label="OSS" />
        </Tabs>
      </Paper>

      <ItaskPage
        active={page === 'itask'}
        connection={connection}
        onConnectionChange={setConnection}
        onDefaultUserChange={setOssUser}
        onRequestItask={() => setPage('itask')}
      />
      <OssPage active={page === 'oss'} connectedPod={connection?.pod || null} preferredUser={ossUser} />
    </Container>
  );
}
