import { Alert, AlertTitle, Stack } from '@mui/material';

export default function ReadinessAlerts({ items = [], fallback }) {
  const missing = items.filter((item) => item && !item.ready);
  if (!missing.length && !fallback) return null;
  return (
    <Stack spacing={1} sx={{ mb: 2 }}>
      {fallback ? <Alert severity="warning">{fallback}</Alert> : null}
      {missing.map((item) => (
        <Alert severity="warning" key={item.id}>
          <AlertTitle>{item.label}</AlertTitle>
          {item.detail}
        </Alert>
      ))}
    </Stack>
  );
}
