import {
  Alert, Autocomplete, Box, Button, Checkbox, Collapse, Dialog, DialogActions, DialogContent,
  DialogTitle, FormControl, FormControlLabel, InputLabel, MenuItem, Select, Stack, TextField, Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { api, jsonOptions, podUrl } from '../../api.js';
import { ConfirmDialog } from '../../components/Dialogs.jsx';
import { monoFont } from '../../theme.js';
import FilesystemPickerDialog from './FilesystemPickerDialog.jsx';
import OssObjectPickerDialog from './OssObjectPickerDialog.jsx';
import { joinPath, normalizeOssKey, sourceName, uploadKey } from './ossUtils.js';

const sourceLabels = { file: '来源类型：文件', directory: '来源类型：目录', object: '来源类型：OSS 单对象', prefix: '来源类型：OSS 目录前缀' };

export default function OssTransferDialog({ open, transfer, users, defaultUser, connectedPod, remoteRoot, readiness, defaultExcludes, objectStore, onClose, onTask }) {
  const [form, setForm] = useState({ user: '', filesystemPath: '', ossKey: '', sourceKind: null, packageUpload: false, extractDownload: false, conflictPolicy: 'overwrite', excludes: '' });
  const [filesystemPicker, setFilesystemPicker] = useState(false);
  const [objectPicker, setObjectPicker] = useState(false);
  const [advanced, setAdvanced] = useState(false);
  const [message, setMessage] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [pendingBody, setPendingBody] = useState(null);

  useEffect(() => {
    if (!open || !transfer) return;
    setForm({
      user: defaultUser || '', filesystemPath: '', ossKey: transfer.initialKey || '', sourceKind: transfer.initialKind || null,
      packageUpload: false, extractDownload: false, conflictPolicy: 'overwrite', excludes: (defaultExcludes || []).join('\n'),
    });
    setFilesystemPicker(false);
    setObjectPicker(false);
    setAdvanced(false);
    setMessage(null);
    setPendingBody(null);
  }, [defaultExcludes, defaultUser, open, transfer]);

  const direction = transfer?.direction;
  const side = transfer?.side;
  const upload = direction === 'upload';
  const selectedFilesystemPath = form.filesystemPath.trim();
  const key = upload ? uploadKey(selectedFilesystemPath, form.sourceKind, form.packageUpload) : normalizeOssKey(form.ossKey);
  const filesystemPath = !upload && form.sourceKind === 'object' && !form.extractDownload
    ? joinPath(selectedFilesystemPath, sourceName(key)) : selectedFilesystemPath;
  const title = side === 'local' ? (upload ? '本地 → OSS' : 'OSS → 本地') : (upload ? 'Pod → OSS' : 'OSS → Pod');
  const filesystemLabel = upload ? (side === 'local' ? '本机来源路径' : 'Pod 来源路径') : (side === 'local' ? '本机目标目录' : 'Pod 目标目录');
  const sourceDescription = sourceLabels[form.sourceKind] || (upload ? '请选择一个文件或目录' : '请选择 OSS 对象或目录前缀');

  const preview = useMemo(() => {
    if (upload && selectedFilesystemPath && key) {
      const behavior = form.sourceKind === 'directory'
        ? (form.packageUpload ? '目录将先打包为 tar，再上传为单对象' : '目录将直接同步，不打包且不删除目标独有对象')
        : '文件将作为单对象上传';
      return { target: `自动上传到：${form.user ? `${form.user}/${key}` : key}`, detail: `${behavior}；目标由来源名称自动生成。` };
    }
    if (!upload && filesystemPath && key) {
      const behavior = form.sourceKind === 'prefix' ? '前缀内容将合并到目标目录，不删除目标独有文件' : (form.extractDownload ? '对象下载后将解包到目标目录' : '对象将下载到目标目录');
      const policy = form.conflictPolicy === 'skip' ? '同名项跳过' : '同名项覆盖（提交前需确认）';
      return { target: `目标：${side === 'local' ? '本机' : `Pod ${connectedPod || ''}`} ${filesystemPath}`, detail: `OSS 来源：${form.user ? `${form.user}/${key}` : key}\n${behavior}；${policy}。` };
    }
    return null;
  }, [connectedPod, filesystemPath, form.conflictPolicy, form.extractDownload, form.packageUpload, form.sourceKind, form.user, key, selectedFilesystemPath, side, upload]);

  const buildBody = () => ({
    user: form.user.trim(), direction, filesystem_path: filesystemPath, oss_key: upload ? '' : key,
    source_kind: form.sourceKind, package_upload: upload && form.sourceKind === 'directory' && form.packageUpload,
    extract_download: !upload && form.sourceKind === 'object' && form.extractDownload,
    conflict_policy: upload ? 'overwrite' : form.conflictPolicy,
    excludes: form.excludes.split('\n').map((value) => value.trim()).filter(Boolean),
  });

  const start = async (body) => {
    setSubmitting(true);
    setMessage({ text: '正在创建任务…', severity: 'info' });
    try {
      const endpoint = side === 'local' ? '/api/oss/transfers' : podUrl(connectedPod, '/oss/transfers');
      const task = await api(endpoint, jsonOptions('POST', body));
      onTask(task);
      onClose();
    } catch (error) {
      setMessage({ text: `无法启动传输：${error.message}`, severity: 'error' });
    } finally {
      setSubmitting(false);
    }
  };

  const submit = (event) => {
    event.preventDefault();
    if (!form.user.trim() || !selectedFilesystemPath || !filesystemPath || !form.sourceKind || (!upload && !key)) {
      setMessage({ text: upload ? '请完整选择 OSS 用户和上传来源' : '请完整选择 OSS 用户、目标目录和 OSS 对象或前缀', severity: 'error' });
      return;
    }
    if (upload && !key) {
      setMessage({ text: '不能直接上传文件系统根目录，请选择其中的文件或目录', severity: 'error' });
      return;
    }
    if (side === 'remote' && !connectedPod) {
      setMessage({ text: 'Pod 已断开，请重新连接', severity: 'error' });
      return;
    }
    const needsLocalRsync = side === 'local' && !upload && (form.sourceKind === 'prefix' || (form.sourceKind === 'object' && form.extractDownload));
    if (needsLocalRsync && readiness?.dependencies?.rsync !== true) {
      setMessage({ text: '本机目录合并依赖 rsync，请先按 README 完成安装', severity: 'error' });
      return;
    }
    const body = buildBody();
    if (!upload && form.conflictPolicy === 'overwrite') setPendingBody(body);
    else start(body);
  };

  const updateKey = (value) => {
    const normalized = normalizeOssKey(value);
    setForm((current) => ({ ...current, ossKey: value, sourceKind: normalized ? (normalized.endsWith('/') ? 'prefix' : 'object') : null, extractDownload: normalized.endsWith('/') ? false : current.extractDownload }));
  };

  return (
    <>
      <Dialog
        open={open}
        onClose={submitting ? undefined : onClose}
        fullWidth
        maxWidth="sm"
        slotProps={{ paper: { component: 'form', onSubmit: submit, noValidate: true } }}
      >
        <DialogTitle>{title}</DialogTitle>
        <DialogContent dividers>
          <Stack spacing={1.5}>
            <Typography variant="body2" color="text.secondary">{side === 'remote' ? `当前 Pod：${connectedPod || ''}` : '本机文件系统'}</Typography>
            <Autocomplete freeSolo options={users || []} inputValue={form.user} onInputChange={(_, value) => setForm((current) => ({ ...current, user: value }))} renderInput={(params) => <TextField {...params} autoFocus label="OSS 用户" required />} />
            <Stack direction="row" spacing={1} sx={{ alignItems: 'flex-start' }}>
              <TextField fullWidth label={filesystemLabel} value={form.filesystemPath} InputProps={{ readOnly: true }} required sx={{ '& input': { fontFamily: monoFont } }} />
              <Button type="button" variant="outlined" sx={{ height: 36 }} onClick={() => setFilesystemPicker(true)}>选择</Button>
            </Stack>
            {!upload ? (
              <Stack direction="row" spacing={1} sx={{ alignItems: 'flex-start' }}>
                <TextField fullWidth label="OSS 来源对象 / 前缀" value={form.ossKey} onChange={(event) => updateKey(event.target.value)} placeholder="选择对象或目录前缀" required sx={{ '& input': { fontFamily: monoFont } }} />
                <Button type="button" variant="outlined" sx={{ height: 36 }} onClick={() => {
                  if (!form.user.trim()) setMessage({ text: '请先填写 OSS 用户', severity: 'error' });
                  else setObjectPicker(true);
                }}>选择</Button>
              </Stack>
            ) : null}
            <Alert severity="info">{sourceDescription}</Alert>
            {upload && form.sourceKind === 'directory' ? <FormControlLabel control={<Checkbox checked={form.packageUpload} onChange={(event) => setForm((current) => ({ ...current, packageUpload: event.target.checked }))} />} label="目录打包为 .tar 后上传" /> : null}
            {!upload && form.sourceKind === 'object' ? <FormControlLabel control={<Checkbox checked={form.extractDownload} onChange={(event) => setForm((current) => ({ ...current, extractDownload: event.target.checked }))} />} label="下载后解包" /> : null}
            {!upload ? (
              <FormControl><InputLabel id="oss-conflict-policy-label">下载冲突策略</InputLabel><Select labelId="oss-conflict-policy-label" label="下载冲突策略" value={form.conflictPolicy} onChange={(event) => setForm((current) => ({ ...current, conflictPolicy: event.target.value }))}><MenuItem value="overwrite">覆盖</MenuItem><MenuItem value="skip">跳过</MenuItem></Select></FormControl>
            ) : null}
            <Box>
              <Button type="button" size="small" variant="text" onClick={() => setAdvanced((value) => !value)}>高级选项</Button>
              <Collapse in={advanced}><TextField fullWidth multiline minRows={4} label="排除规则（每行一条）" value={form.excludes} onChange={(event) => setForm((current) => ({ ...current, excludes: event.target.value }))} placeholder="例如 *.tmp" sx={{ mt: 1 }} /></Collapse>
            </Box>
            {preview ? <Alert severity="success" sx={{ whiteSpace: 'pre-line' }}><strong>{preview.target}</strong>{`\n${preview.detail}`}</Alert> : null}
            {message ? <Alert severity={message.severity}>{message.text}</Alert> : null}
          </Stack>
        </DialogContent>
        <DialogActions><Button type="button" onClick={onClose} disabled={submitting}>取消</Button><Button type="submit" variant="contained" disabled={submitting}>开始传输</Button></DialogActions>
      </Dialog>
      <FilesystemPickerDialog open={filesystemPicker} side={side} mode={upload ? 'source' : 'directory'} pod={connectedPod} initialPath={form.filesystemPath} remoteRoot={remoteRoot} onClose={() => setFilesystemPicker(false)} onSelect={(selection) => { setForm((current) => ({ ...current, filesystemPath: selection.path, sourceKind: upload ? selection.kind : current.sourceKind })); setFilesystemPicker(false); }} />
      <OssObjectPickerDialog open={objectPicker} side="local" user={form.user.trim()} objectStore={objectStore} onClose={() => setObjectPicker(false)} onSelect={(selection) => { setForm((current) => ({ ...current, ossKey: selection.key, sourceKind: selection.kind, extractDownload: selection.kind === 'object' ? current.extractDownload : false })); setObjectPicker(false); }} />
      <ConfirmDialog open={!!pendingBody} danger title="确认覆盖" message="覆盖模式会替换目标中的同名文件，且不可恢复。确认继续吗？" confirmText="继续传输" onClose={() => setPendingBody(null)} onConfirm={() => { const body = pendingBody; setPendingBody(null); start(body); }} />
    </>
  );
}
