import { Button, Stack, Typography } from '@mui/material';
import { monoFont } from '../../theme.js';
import { ossBreadcrumbs } from './ossUtils.js';

export default function OssBreadcrumbs({ prefix, onOpen, label = 'OSS 对象路径' }) {
  const crumbs = ossBreadcrumbs(prefix);
  return (
    <Stack component="nav" aria-label={label} direction="row" spacing={0.25} sx={{ minHeight: 32, fontFamily: monoFont, alignItems: 'center', flexWrap: 'wrap' }}>
      {crumbs.map((crumb, index) => (
        <Stack key={crumb.prefix || 'root'} direction="row" spacing={0.25} sx={{ alignItems: 'center' }}>
          {index ? <Typography color="text.secondary">/</Typography> : null}
          <Button size="small" variant="text" disabled={index === crumbs.length - 1} onClick={() => onOpen(crumb.prefix)} sx={{ minWidth: 0, px: 0.75, fontFamily: monoFont }}>
            {crumb.label}
          </Button>
        </Stack>
      ))}
    </Stack>
  );
}
