import { Box } from '@mui/material';

const toneStyles = {
  neutral: { background: 'action.hover', dot: 'text.disabled' },
  success: { background: '#ecfdf3', dot: 'success.main' },
  warning: { background: '#fff8e1', dot: 'warning.main' },
  error: { background: '#fff1f2', dot: 'error.main' },
};

export default function StatusBadge({ label, tone = 'neutral', title = '', onClick, disabled = false }) {
  const colors = toneStyles[tone] || toneStyles.neutral;
  const interactive = typeof onClick === 'function';
  return (
    <Box
      component={interactive ? 'button' : 'span'}
      type={interactive ? 'button' : undefined}
      title={title}
      aria-label={interactive ? label : undefined}
      disabled={interactive ? disabled : undefined}
      onClick={interactive ? onClick : undefined}
      data-status-badge
      data-status-tone={tone}
      sx={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 0.75,
        px: 1.25,
        py: 0.6,
        border: 0,
        borderRadius: 999,
        bgcolor: colors.background,
        color: 'inherit',
        fontFamily: 'inherit',
        fontSize: '0.875rem',
        fontWeight: 650,
        lineHeight: 1.43,
        whiteSpace: 'nowrap',
        cursor: interactive && !disabled ? 'pointer' : 'default',
        transition: 'filter 120ms ease, box-shadow 120ms ease, opacity 120ms ease',
        '&:hover': interactive && !disabled ? { filter: 'brightness(0.97)' } : undefined,
        '&:focus-visible': interactive ? { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 } : undefined,
        '&:disabled': { opacity: 0.7 },
      }}
    >
      <Box component="span" sx={{ width: 8, height: 8, flex: '0 0 auto', borderRadius: '50%', bgcolor: colors.dot }} />
      {label}
    </Box>
  );
}
