import { Alert, Box, Button, Paper, Stack, Tab, Tabs, Typography } from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { api } from '../../api.js';
import OssConfigPanel, { readinessMessage } from './OssConfigPanel.jsx';
import OssObjectBrowser from './OssObjectBrowser.jsx';
import OssTaskPanel from './OssTaskPanel.jsx';
import OssTransferDialog from './OssTransferDialog.jsx';
import useOssObjects from './useOssObjects.js';
import useOssTask from './useOssTask.js';

function StableTabPanel({ value, name, labelledBy, children }) {
  return (
    <Box
      role="tabpanel"
      id={`oss-${name}-tabpanel`}
      aria-labelledby={labelledBy}
      hidden={value !== name}
      sx={{ p: { xs: 1.5, sm: 2 }, '&[hidden]': { display: 'none' } }}
    >
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, minmax(0, 1fr))' }, gap: 1.5 }}>
        {children}
      </Box>
    </Box>
  );
}

function OperationCard({ title, description, disabled, onClick }) {
  return (
    <Button
      variant="outlined"
      disabled={disabled}
      onClick={onClick}
      sx={{
        minHeight: 112,
        p: 2,
        alignItems: 'flex-start',
        flexDirection: 'column',
        textAlign: 'left',
        bgcolor: 'background.paper',
        borderColor: 'divider',
        color: 'text.primary',
        '&:hover': { borderColor: 'primary.main', bgcolor: '#f8faff' },
      }}
    >
      <Typography component="span" variant="subtitle1">{title}</Typography>
      <Typography component="span" variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>{description}</Typography>
    </Button>
  );
}

export default function OssPage({ active, connectedPod, preferredUser }) {
  const [config, setConfig] = useState(null);
  const [configError, setConfigError] = useState('');
  const [readiness, setReadiness] = useState(null);
  const [readinessError, setReadinessError] = useState('');
  const [side, setSide] = useState('local');
  const [objectUser, setObjectUser] = useState('');
  const [transferUser, setTransferUser] = useState('');
  const [transfer, setTransfer] = useState(null);
  const [refreshNonce, setRefreshNonce] = useState(0);
  const initializationToken = useRef(0);
  const objectStore = useOssObjects();
  const taskController = useOssTask({
    onUploadDone: (task) => {
      objectStore.invalidate();
      if (task.user === objectUser.trim()) setRefreshNonce((value) => value + 1);
    },
  });

  useEffect(() => {
    if (preferredUser !== undefined) {
      setTransferUser(preferredUser);
      setObjectUser(preferredUser);
    }
  }, [preferredUser]);

  useEffect(() => {
    const token = ++initializationToken.current;
    (async () => {
      try {
        const nextConfig = await api('/api/config');
        if (token !== initializationToken.current) return;
        setConfig(nextConfig);
        setConfigError('');
        setTransferUser((current) => current || nextConfig.defaults?.user || '');
        setObjectUser((current) => current || nextConfig.defaults?.user || '');
      } catch (error) {
        if (token === initializationToken.current) setConfigError(`初始化失败：${error.message}`);
      }
      try {
        const nextReadiness = await api('/api/oss/readiness');
        if (token !== initializationToken.current) return;
        setReadiness(nextReadiness);
        setReadinessError('');
        setRefreshNonce((value) => value + 1);
      } catch (error) {
        if (token === initializationToken.current) setReadinessError(`OSS 环境检测失败：${error.message}`);
      }
      if (token === initializationToken.current) await taskController.recover();
    })();
    return () => { initializationToken.current += 1; };
  }, [taskController.recover]);

  const baseStatus = configError
    ? { text: configError, severity: 'error' }
    : readinessError
      ? { text: readinessError, severity: 'error' }
      : readiness ? readinessMessage(readiness) : { text: '正在检查...', severity: 'info' };
  const visibleStatus = taskController.status || baseStatus;
  const localReady = (readiness?.capabilities?.local_transfer ?? readiness?.capabilities?.transfer) === true;
  const remoteReady = readiness?.config?.valid === true;
  const openTransfer = (targetSide, direction, initial = {}) => {
    if (taskController.busy) return;
    if (targetSide === 'remote' && !connectedPod) return;
    setTransfer({ side: targetSide, direction, initialKind: initial.kind || null, initialKey: initial.key || '' });
  };

  return (
    <Box sx={{ display: active ? 'block' : 'none' }}>
      <Stack spacing={2}>
        <Paper variant="outlined" sx={{ p: 2 }}>
          <Stack spacing={1.5}>
            <Stack direction={{ xs: 'column', sm: 'row' }} sx={{ alignItems: { sm: 'center' }, justifyContent: 'space-between', gap: 1 }}>
              <Typography variant="h6">OSS 管理</Typography>
              <Typography variant="body2" color={visibleStatus.severity === 'error' ? 'error' : 'text.secondary'} sx={{ ml: { sm: 'auto' }, textAlign: { sm: 'right' } }}>{visibleStatus.text}</Typography>
            </Stack>
            <OssConfigPanel readiness={readiness} onReadiness={setReadiness} onConfigured={() => { objectStore.invalidate(); setRefreshNonce((value) => value + 1); }} />
            <Box>
              <Tabs
                value={side}
                onChange={(_, value) => setSide(value)}
                aria-label="OSS 操作位置"
                sx={{
                  minHeight: 48,
                  '& .MuiTabs-flexContainer': { alignItems: 'flex-end', gap: 0.5 },
                  '& .MuiTab-root': {
                    minHeight: 48,
                    px: 2.5,
                    borderRadius: '10px 10px 0 0',
                    color: 'text.secondary',
                    fontWeight: 600,
                  },
                  '& .MuiTab-root.Mui-selected': {
                    bgcolor: '#eef4ff',
                    color: 'primary.main',
                    fontWeight: 700,
                    boxShadow: 'inset 0 3px 0 #2563eb',
                  },
                  '& .MuiTabs-indicator': { display: 'none' },
                }}
              >
                <Tab id="oss-local-tab" value="local" label="本地操作" aria-controls="oss-local-tabpanel" />
                <Tab id="oss-remote-tab" value="remote" label="远端操作" aria-controls="oss-remote-tabpanel" />
              </Tabs>
              <Box sx={{ overflow: 'hidden', bgcolor: '#eef4ff', borderRadius: side === 'local' ? '0 12px 12px 12px' : '12px' }}>
                {side === 'remote' && !connectedPod ? <Alert severity="warning" sx={{ m: 2, mb: 0 }}>请先连接 Pod，远端操作才可用。</Alert> : null}
                <StableTabPanel value={side} name="local" labelledBy="oss-local-tab">
                  <OperationCard title="本地 → OSS" description="上传文件或目录" disabled={taskController.busy || !localReady} onClick={() => openTransfer('local', 'upload')} />
                  <OperationCard title="OSS → 本地" description="下载对象或目录前缀" disabled={taskController.busy || !localReady} onClick={() => openTransfer('local', 'download')} />
                </StableTabPanel>
                <StableTabPanel value={side} name="remote" labelledBy="oss-remote-tab">
                  <OperationCard title="Pod → OSS" description="上传 Pod 文件或目录" disabled={taskController.busy || !connectedPod || !remoteReady} onClick={() => openTransfer('remote', 'upload')} />
                  <OperationCard title="OSS → Pod" description="下载到 Pod 目录" disabled={taskController.busy || !connectedPod || !remoteReady} onClick={() => openTransfer('remote', 'download')} />
                </StableTabPanel>
              </Box>
            </Box>
            <OssTaskPanel task={taskController.task} activeSide={side} busy={taskController.busy} cancelling={taskController.cancelling} lastProgressPhase={taskController.lastProgressPhase} onCancel={taskController.cancel} />
          </Stack>
        </Paper>
        <OssObjectBrowser
          active={active}
          user={objectUser}
          users={config?.users || []}
          ready={localReady}
          busy={taskController.busy}
          objectStore={objectStore}
          refreshNonce={refreshNonce}
          onUserChange={setObjectUser}
          onDownload={(kind, key) => openTransfer('local', 'download', { kind, key })}
        />
      </Stack>
      <OssTransferDialog
        open={!!transfer}
        transfer={transfer}
        users={config?.users || []}
        defaultUser={transferUser}
        connectedPod={connectedPod}
        remoteRoot={config?.remote_root || '/root'}
        readiness={readiness}
        defaultExcludes={readiness?.default_excludes || []}
        objectStore={objectStore}
        onClose={() => setTransfer(null)}
        onTask={taskController.acceptTask}
      />
    </Box>
  );
}
