import { Alert, Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, List, ListItemButton, ListItemText, Stack, Typography } from '@mui/material';
import { useCallback, useEffect, useRef, useState } from 'react';
import { monoFont } from '../../theme.js';
import { formatBytes } from '../../utils.js';
import OssBreadcrumbs from './OssBreadcrumbs.jsx';

export default function OssObjectPickerDialog({ open, side, pod, user, objectStore, onClose, onSelect }) {
  const [prefix, setPrefix] = useState('');
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const requestToken = useRef(0);

  const loadPrefix = useCallback(async (nextPrefix, force = false) => {
    const token = ++requestToken.current;
    setPrefix(nextPrefix);
    setEntries([]);
    setLoading(true);
    setError('');
    try {
      const objects = await objectStore.load(side, user, nextPrefix, force, pod);
      if (token !== requestToken.current || objects === null) return;
      setEntries(objects);
    } catch (requestError) {
      if (token === requestToken.current) setError(`加载失败：${requestError.message}。可关闭此窗口后手工输入 OSS key。`);
    } finally {
      if (token === requestToken.current) setLoading(false);
    }
  }, [objectStore, pod, side, user]);

  useEffect(() => {
    if (!open) { requestToken.current += 1; return; }
    loadPrefix('', true);
    return () => { requestToken.current += 1; };
  }, [open, loadPrefix]);

  const directories = entries.filter((entry) => entry.kind === 'directory');
  const files = entries.filter((entry) => entry.kind === 'object');
  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>选择 OSS 对象或前缀</DialogTitle>
      <DialogContent dividers>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>对象可下载并解包；前缀用于下载目录内容。</Typography>
        <Stack direction={{ xs: 'column', sm: 'row' }} sx={{ mb: 1, justifyContent: 'space-between', alignItems: { sm: 'center' }, gap: 1 }}>
          <OssBreadcrumbs prefix={prefix} onOpen={(nextPrefix) => { if (!loading) loadPrefix(nextPrefix); }} label="OSS 选择路径" />
          {prefix ? <Button size="small" variant="outlined" disabled={loading || !!error} onClick={() => onSelect({ kind: 'prefix', key: prefix })}>选择当前目录</Button> : null}
        </Stack>
        {error ? <Alert severity="error" sx={{ mb: 1 }}>{error}</Alert> : null}
        <Box sx={{ minHeight: 260, maxHeight: 440, overflow: 'auto', border: 1, borderColor: 'divider', borderRadius: 1 }}>
          <List dense disablePadding>
            {directories.map((entry) => (
              <ListItemButton key={entry.key} disabled={loading || !!error} onClick={() => loadPrefix(entry.key)}>
                <ListItemText primary={`📁 ${entry.name}/`} secondary="打开" primaryTypographyProps={{ fontFamily: monoFont }} />
              </ListItemButton>
            ))}
            {files.map((entry) => (
              <ListItemButton key={entry.key} disabled={loading || !!error} onClick={() => onSelect({ kind: 'object', key: entry.key })}>
                <ListItemText primary={entry.name} secondary={formatBytes(entry.size)} primaryTypographyProps={{ fontFamily: monoFont }} />
              </ListItemButton>
            ))}
          </List>
          {!loading && !entries.length && !error ? <Typography color="text.secondary" align="center" sx={{ py: 6 }}>当前目录为空</Typography> : null}
        </Box>
      </DialogContent>
      <DialogActions><Button onClick={onClose}>关闭</Button></DialogActions>
    </Dialog>
  );
}
